comms.text:
@1 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@2 מַלֵל עִם כָּל כְּנִשְׁתָּא דִבְנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן קַדִישִׁין תְּהוֹן אֲרֵי קַדִישׁ אֲנָא יְיָ אֱלָהָכוֹן:
@3 גְבַר מִן אִמֵהּ וּמִן אֲבוּהִי תְּהוֹן דָחֲלִין וְיָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן אֲנָא יְיָ אֱלָהָכוֹן:
@4 לָא תִתְפְּנוּן בָּתַר טַעֲוָן וְדַחֲלָן דְמַתְּכָא לָא תַעְבְּדוּן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@5 וַאֲרֵי תִכְסוּן נִכְסַת קוּדְשַׁיָא קֳדָם יְיָ לְרַעֲוָא לְכוֹן תִּכְסֻנֵהּ:
@6 בְּיוֹמָא דְיִתְנְכֵס יִתְאֲכֵל וּבְיוֹמָא דְבַתְרוֹהִי וּדְאִשְׁתָּאַר עַד יוֹמָא תְלִיתָאָה בְּנוּרָא יִתּוֹקָד:
@7 וְאִם אִתְאֲכָלָא יִתְאֲכֵל בְּיוֹמָא תְלִיתָאָה מְרָחַק הוּא לָא יְהֵי לְרַעַוָא:
@8 וּדְיֵיכְלִנֵהּ חוֹבֵהּ יְקַבֵּל אֲרֵי יָת קוּדְשָׁא דַיְיָ אַחֵל וְיִשְׁתֵּיצֵי אֲנָשָׁא הַהוּא מֵעַמֵהּ:
@9 וּבְמֶחְצָדְכוֹן יָת חֲצָדָא דְאַרְעֲכוֹן לָא תְשֵׁיצֵי פָּאתָא דְחַקְלָךְ לְמֶחְצָד וּלְקָטָא דַחֲצָדָךְ לָא תְלַקֵט:
@10 וְכַרְמָךְ לָא תְעַלֵל וְנִתְרָא דְכַרְמָךְ לָא תְלַקֵט לְעַנְיֵי וּלְגִיוֹרֵי תִּשְׁבּוֹק יָתְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@11 לָא תִּגְנְבוּן וְלָא תְכַדְבוּן וְלָא תְשַׁקְרוּן אֱנַשׁ בְּחַבְרֵהּ:
@12 וְלָא תִשָׁבְעוּן בִּשְׁמִי לְשִׁקְרָא וְתַחֵל יָת שְׁמָא דֶאֱלָהָךְ אֲנָא יְיָ:
@13 לָא תַעֲשׁוֹק יָת חַבְרָךְ וְלָא תְאַנֵס לָא תְבִית אַגְרָא דַאֲגִירָא לְוָתָךְ עַד צַפְרָא:
@14 לָא תְלוּטּ דְלָא שָׁמַע וְקֳדָם דְלָא חָזֵי לָא תְשִׂים תַּקְלָא וְתִדְחַל מֵאֱלָהָךְ אֲנָא יְיָ:
@15 לָא תַעְבְּדוּן שְׁקַר בְּדִינָא לָא תִסַב אַפֵּי מַסְכֵּנָא וְלָא תֶהְדַר אַפֵּי רַבָּא בְּקוּשְׁטָא תְּדִינֵהּ לְחַבְרָךְ:
@16 לָא תֵיכוּל קוּרְצִין בְּעַמָךְ לָא תְקוּם עַל דְמָא דְחַבְרָךְ אֲנָא יְיָ:
@17 לָא תִשְׂנֵי יָת אֲחוּךְ בְּלִבָּךְ אוֹכָחָא תוֹכַח יָת חַבְרָךְ וְלָא תְקַבֵּל עַל דִי לֵהּ חוֹבָא:
@18 לָא תִקוֹם וְלָא תִטַר דְבָבוּ לִבְנֵי עַמָךְ וּתְרַחֵם לְחַבְרָךְ כְּוָתָךְ אֲנָא יְיָ:
@19 יָת קְיָמַי תִּטְרוּן בְּעִירָךְ לָא תַרְכֵּב עֵרוּבִין חַקְלָךְ לָא תִזְרַע עֵרוּבִין וּלְבוּשׁ עֵרוּבִין שַׁעַטְנֵזָא לָא יִסַק עֲלָךְ:
@20 וּגְבַר אֲרֵי יִשְׁכּוּב עִם אִתְּתָא שִׁכְבַת זַרְעָא וְהִיא אַמְתָא אֲחִידָא לִגְבַר וְאִתְפְּרָקָא לָא אִתְפְּרִיקַת בְּכַסְפָּא אוֹ חֵרוּתָא לָא אִתְיְהִיבַת לַהּ בִּשְׁטָר בִּקֻּרְתָּא תְהֵי לָא יוּמְתוּן אֲרֵי לָא אִתְחָרָרַת:
@21 וְיַיְתִי יָת אַשְׁמֵהּ קֳדָם יְיָ לִתְרַע מַשְׁכַּן זִמְנָא דְכַר לַאֲשָׁמָא:
@22 וִיכַפֵּר עֲלוֹהִי כַּהֲנָא בְּדִכְרָא דַאֲשָׁמָא קֳדָם יְיָ עַל חוֹבְתֵהּ דִי חָב וְיִשְׁתְּבֵק לֵהּ מְחוֹבְתֵהּ דִי חַב:
@23 וַאֲרֵי תֵעֲלוּן לְאַרְעָא וְתִצְבוּן כָּל אִלָן דְמֵיכַל וּתְרַחֲקוּן רָחָקָא יַת אִבֵּהּ תְּלַת שְׁנִין יְהֵי לְכוֹן מְרָחָק לַאֲבָדָא לָא יִתְאֲכֵל:
@24 וּבְשַׁתָּא רְבִיעֵתָא יְהֵי כָּל אִבֵּהּ קֹדֶשׁ תּוּשְׁבְּחָן קֳדָם יְיָ:
@25 וּבְשַׁתָּא חֲמִישֵׁתָא תֵּיכְלוּן יָת אִבֵּהּ לְאוֹסָפָא לְכוֹן עֲלַלְתֵּהּ אֲנָא יְיָ אֱלָהָכוֹן:
@26 לָא תֵיכְלוּן עַל דְמָא לָא תְנַחֲשׁוּן וְלָא תְעוֹנוּן:
@27 לָא תַקְפוּן פָּאתָא דְרֵישְׁכוֹן וְלָא תְחַבֵּל יָת פָּאתָא דְדִקְנָךְ:
@28 וְחִבּוּל עַל מִית לָא תִתְּנוּן בְּבִסְרְכוֹן וְרוּשְׁמִין חֲרִיתִין לָא תִתְּנוּן בְכוֹן אֲנָא יְיָ:
@29 לָא תַחֵל יָת בְּרַתָּךְ לְאַטְעֲיוּתַהּ וְלָא תִטְעֵי אַרְעָא וְתִתְמְלֵי אַרְעָא עֵצַת חִטְאִין:
@30 יָת יוֹמֵי שַׁבַּיָא דִילִי תִּטְרוּן וּלְבֵית מַקְדְשִׁי תְּהוֹן דָחֲלִין אֲנָא יְיָ:
@31 לָא תִתְפְּנוּן בָּתַר בִּדִין וּדְכוּרוּ לָא תִתְבְּעוּן לְאִסְתָּאָבָא בְהוֹן אֲנָא יְיָ אֱלָהָכוֹן:
@32 מִן קֳדָם דְסַבַּר בְּאוֹרַיְתָא תְּקוּם וּתְהַדַר אַפֵּי סָבָא וְתִדְחַל מֵאֳלָהָךְ אֲנָא יְיָ:
@33 וַאֲרֵי יִתְגַיַר עִמָךְ גִיוֹרָא בְּאַרְעֲכוֹן לָא תוֹנוּן יָתֵהּ:
@34 כְּיַצִיבָא מִנְכוֹן יְהֵי לְכוֹן גִיוֹרָא דְיִתְגַיַר בֵּינֵיכוֹן וּתְרַחֵם לֵהּ כְּוָתָךְ אֲרֵי דַיָרִין הֲוֵיתוּן בְּאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:
@35 לָא תַעְבְּדוּן שְׁקַר בְּדִין בִּמְשַׁחְתָּא בְּמַתְקְלָא וּבִמְכִלְתָּא:
@36 מֹאזְנָוָן דִקְשׁוֹט מַתְקְלָן דִקְשׁוֹט מְכִילָן דִקְשׁוֹט וְהִינִין דִקְשׁוֹט יְהוֹן לְכוֹן אֲנָא יְיָ אֱלָהָכוֹן דִי אֲפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם:
@37 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא יְיָ:
@38 וּמַלִיל יְיָ עִם מֹשֶׁה לְמֵימָר:
@39 וְלִבְנֵי יִשְׂרָאֵל תֵּימַר גְבַר גְבַר מִבְּנֵי יִשְׂרָאֵל וּמִן גִיוֹרָא דְיִתְגַיְרוּן בְּיִשְׂרָאֵל דִי יִתֵּן מִזַרְעֵהּ לְמוֹלֶךְ אִתְקְטָלָא יִתְקְטֵל עַמָא בֵית יִשְׂרָאֵל יִרְגְמֻנֵהּ בְּאַבְנָא:
@40 וַאֲנָא אֶתֵּן יָת רוּגְזִי בְגַבְרָא הַּהוּא וְאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ אֲרֵי מִזַרְעֵהּ יְהַב לְמוֹלֶךְ בְּדִיל לְסָאָבָא יָת מַקְדְשִׁי וּלְאַחַלָא יָת שְׁמָא דְקוּדְשִׁי:
@41 וְאִם מִכְבַּשׁ יִכְבְּשׁוּן עַמָא בֵית יִשְׂרָאֵל יָת עֵינֵיהוֹן מִן גַבְרָא הַהוּא בִּדְיָהֵב מִזַרְעֵהּ לְמוֹלֶךְ בְּדִיל דְלָא לְקַטָלָא יָתֵהּ:
@42 וֶאֱשַׁוֵי אֲנָא יָת רוּגְזִי בְגַבְרָא הַהוּא וּבִסְעָדוֹהִי וֶאֱשֵׁיצֵי יָתֵהּ וְיָת כָּל דְטָעָן בַּתְרוֹהִי לְמִטְעֵי בָּתַר מוֹלֶךְ מִגוֹ עַמְהוֹן:
@43 וֶאֱנַשׁ דִי יִתְפְּנֵי בָּתַר בִּדִין וּדְכוּרוּ לְמִטְעֵי בַתְרֵיהוֹן וְאֶתֵּן יָת רוּגְזִי בַּאֲנָשָׁא הַהִיא וֶאֱשֵׁיצֵי יָתֵהּ מִגוֹ עַמֵהּ:
@44 וְתִתְקַדְשׁוּן וּתְהוֹן קַדִישִׁין אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@45 וְתִטְּרוּן יָת קְיָמַי וְתַעְבְּדוּן יָתְהוֹן אֲנָא:ייָ מַקְדִשְׁכוֹן:
@46 אֲרֵי גְבַר גְבַר דִי יְלוּט יָת אֲבוּהִי וְיָת אִמֵהּ אִתְקְטָּלָא יִתְקְטֵל אֲבוּהִי וְאִמֵהּ לַטּ קְטָלָא חַיָב:
@47 וּגְבַר דִי יְגוּף יָת אִתַּת גְבַר דִי יְגוּף יָת אִתַּת חַבְרֵהּ אִתְקְטָלָא יִתְקְטֵל גַיָפָא וְגַיַפְתָּא:
@48 וּגְבַר דִי יִשְׁכּוּב עִם אִתַּת אֲבוּהִי עֶרְיְתָא דַאֲבוּהִי גַלִי אִתְקַטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן קְטָלָא חַיָבִין:
@49 וּגְבַר דִי יִשְׁכּוּב יָת כַּלָתֵהּ אִתְקְטָלָא יִתְקַטְלוּן תַּרְוֵיהוֹן תִּבְלָא עֲבָדוּ קְטָלָא חַיָבִין:
@50 וּגְבַר דִי יִשְׁכּוּב יָת דְכוּרָא מִשְׁכְּבֵי אִתְּתָא תּוֹעֶבְתָּא עֲבָדוּ תַּרְוֵיהוֹן אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@51 וּגְבַר דִי יִסַב יָת אִתְּתָא וְיָת אִמַהּ עֵצַת חִטְאִין הִיא בְּנוּרָא יוֹקְדוּן יָתֵהּ וְיָתְהֶן וְלָא תְהֵי עֵצַת חִטְאִין בֵּינֵיכוֹן:
@52 וּגְבַר דִי יִתֵּן שְׁכָבְתֵּהּ בִּבְעִירָא אִתְקְטָלָא יִתְקְטֵל וְיָת בְּעִירָא תִּקְטְלוּן:
@53 וְאִתְּתָא דִי תִקְרַב לְכָל בְּעִירָא לְמִשְׁלַט בַּהּ וְתִקְטוֹל יָת אִתְּתָא וְיָת בְּעִירָא אִתְקְטָלָא יִתְקַטְלוּן קְטָלָא חַיָבִין:
@54 וּגְבַר דִי יִסַב יָת אֲחָתֵהּ בַּת אֲבוּהִי אוֹ בַת אִמֵהּ וְיֶחֱזֵי יָת עֶרְיְתַהּ וְהִיא תֶחֱזֵי יָת עֶרְיְתֵהּ קְלָנָא הוּא וְיִשְׁתֵּיצוּן לְעֵינֵי בְּנֵי עַמְהוֹן עֶרְיַת אֲחָתֵהּ גַלִי חוֹבֵהּ יְקַבֵּל:
@55 וּגְבַר דִי יִשְׁכּוּב יָת אִתְּתָא סוֹאֲבָתָא וִיגַלֵי יָת עֶרְיְתַהּ יָת קְלָנַהּ גַלִי וְהִיא תְגַלֵי יָת סוֹאֲבַת דְמָהָא וְיִשְׁתֵּיצוּן תַּרְוֵיהוֹן מִגוֹ עַמְהוֹן:
@56 וְעֶרְיַת אֲחַת אִמָךְ וַאֲחַת אָבוּךְ לָא תְגַלֵי אֲרֵי יָת קָרִיבֵהּ גַלִי חוֹבְהֶן יְקַבְּלוּן:
@57 וּגְבַר דִי יִשְׁכּוּב יָת אִתַּת אַח אֲבוּהִי עֶרְיַת אַח אֲבוּהִי גַלִי חוֹבְהֶן יְקַבְּלּוּן בְּלָּא וְלָד יְמוּתוּן:
@58 וּגְבַר דִי יִסַב יָת אִתַּת אֲחוּהִי מְרָחָקָא הִיא עֶרְיְתָא דַאֲחוּהִי גַלִי בְּלָא וְלָד יְהוֹן:
@59 וְתִטְרוּן יָת כָּל קְיָמַי וְיָת כָּל דִינַי וְתַעְבְּדוּן יָתְהוֹן וְלָא תְרוֹקֵן יָתְכוֹן אַרְעָא דִי אֲנָא מָעֵיל יָתְכוֹן תַּמָן לְמִתַּב בַּהּ:
@60 וְלָא תְהָכוּן בְּנִימוֹסֵי עַמְמַיָא דִי אֲנָא מַגְלֵי מִן קֳדָמֵיכוֹן אֲרֵי יָת כָּל אִלֵין עֲבָדוּ וְרָחִיק מֵימְרִי יָתְהוֹן:
@61 וַאֲמָרִית לְכוֹן אַתּוּן תִּירְתוּן יָת אַרְעֲהוֹן וַאֲנָא אֶתְּנִנַהּ לְכוֹן לְמֵירַת יָתַהּ אַרְעָא עַבְדָא חַלָב וּדְבָשׁ אֲנָא יְיָ אֱלָהָכוֹן דִי אַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא:
@62 וְתַפְרְשׁוּן בֵּין בְּעִירָא דַכְיָא לִמְסָאָבָא וּבֵין עוֹפָא מְסָאָבָא לִדְכֵי וְלָא תְשַׁקְצוּן יָת נַפְשָׁתֵיכוֹן בִּבְעִירָא וּבְעוֹפָא וּבְכֹל דִי תַרְחֵשׁ אַרְעָא דִי אַפְרֵשִׁית לְכוֹן לְסָאָבָא:
@63 וּתְהוֹן קֳדָמַי קַדִישִׁין אֲרֵי קַדִישׁ אֲנָא יְיָ וְאַפְרֵשִׁית יָתְכוֹן מִן עַמְמַיָא לְמֶהֱוֵי פָלְחִין קֳדָמַי:
@64 וּגְבַר אוֹ אִתְּתָא אֲרֵי יְהֵי בְהוֹן בִּדִין אוֹ דְכוּרוּ אִתְקְטָלָא יִתְקַטְלוּן בְּאַבְנָא יִרְגְמוּן יָתְהוֹן קְטָלָא חַיָבִין: פפפ:

@2 **דבר אל כל עדת בני ישראל.** מלמד שנאמרה פרשה זו בהקהל, מפני שרוב גופי תורה תלויין בה: **קדשים תהיו.** הוו פרושים מן העריות ומן העברה, שכל מקום שאתה מוצא גדר ערוה אתה מוצא קדשה, אשה זונה וחללה וגו' אני ה' מקדשכם, (ויקרא כא ז. ח) ולא יחלל זרעו אני ה' מקדשו (ויקרא כא טו) קדשים יהיו אשה זונה וחללה וגו' (ויקרא כא ו. ז) :
@3 **איש אמו ואביו תיראו.** כל אחד מכם תיראו אביו ואמו, זהו פשוטו. ומדרשו אין לי אלא איש, אשה מנין, כשהוא אומר תיראו, הרי כאן שנים אם כן למה נאמר איש, שהאיש ספק בידו לעשות, אבל אשה רשות אחרים עליה: **אמו ואביו תיראו.** כאן הקדים אם לאב, לפי שגלוי לפניו שהבן ירא את אביו יותר מאמו, ובכבוד הקדים אב לאם, לפי שגלוי לפניו שהבן מכבד את אמו יותר מאביו, מפני שמשדלתו בדברים: **ואת שבתתי תשמרו.** סמך שמירת שבת למורא אב, לומר אף על פי שהזהרתיך על מורא אב, אם יאמר לך חלל את השבת אל תשמע לו, וכן בשאר כל המצות: **אני ה' אלהיכם.** אתה ואביך חיבים בכבודי, לפיכך לא תשמע לו לבטל את דברי. איזהו מורא, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. ואיזהו כבוד, מאכיל ומשקה, מלביש ומנעיל, מכניס ומוציא:
@4 **אל תפנו אל האלילם.** לעבדם. אלילים לשון אל, כלא הוא חשוב: **ואלהי מסכה.** תחלתן אלילים הם, ואם אתה פונה אחריהם, סופך לעשותן אלהות: **לא תעשו לכם.** לא תעשו לאחרים ולא אחרים לכם. ואם תאמר לא תעשו לעצמכם אבל אחרים עושין לכם, הרי כבר נאמר (שמות כ ג) לא יהיה לך, לא שלך ולא של אחרים:
@5 **וכי תזבחו** וגו' **.** לא נאמרה פרשה זו אלא ללמד שלא תהא זביחתן אלא על מנת להאכל בתוך הזמן הזה, שאם לקבוע להם זמן אכילה, הרי כבר נאמר (ויקרא ז טז) ואם נדר או נדבה זבח קרבנו וגו' : **לרצנכם תזבחהו.** תחלת זביחתו תהא על מנת נחת רוח שיהא לכם לרצון, שאם תחשבו עליו מחשבת פסול לא ירצה עליכם לפני: **לרצנכם.** אפיימנ''ט [פיוס] . זהו לפי פשוטו. ורבותינו למדו (חולין יג א) , מכאן למתעסק בקדשים שפסול, שצריך שיתכון לשחוט:
@6 **ביום זבחכם יאכל.** כשתזבחוהו, תשחטוהו על מנת לאכלו בזמן שקבעתי לכם כבר:
@7 **ואם האכל יאכל** וגו' **.** אם אינו ענין לחוץ לזמנו, שהרי כבר נאמר (ויקרא ז יח) ואם האכל יאכל מבשר זבח שלמיו וגו' , תנהו ענין לחוץ למקומו. יכול יהיו חייבין כרת על אכילתו, תלמוד לומר (שם) והנפש האכלת ממנו עונה תשא, ממנו ולא מחברו, יצא הנשחט במחשבת חוץ למקומו: **פגול.** מתועב, כמו (ישעיה סה ד) ומרק פגולים כליהם:
@8 **ואכליו עונו ישא.** בנותר גמור הכתוב מדבר ואינו ענוש כרת על הנשחט חוץ למקומו שכבר מיעטו הכתוב. וזהו בנותר גמור מדבר. ובמסכת כריתות (ה א) למדוהו מגזרה שוה:
@9 **לא תכלה פאת שדך.** שיניח פאה בסוף שדהו: **ולקט קצירך.** שבלים הנושרים בשעת קצירה אחת או שתים, אבל שלש אינן לקט:
@10 **לא תעולל.** לא תטל עוללות שבה והן נכרות. איזהו עוללות כל שאין לה לא כתף ולא נטף: **ופרט כרמך.** גרגרי ענבים הנושרים בשעת בצירה: **אני ה' אלהיכם.** דין להפרע ואיני גובה מכם אלא נפשות, שנאמר (משלי כב. כג) אל תגזל דל וגו' כי ה' יריב ריבם וגו' :
@11 **לא תגנבו.** אזהרה לגונב ממון, אבל לא תגנוב (שמות כ יג) שבעשרת הדברות, אזהרה לגונב נפשות, דבר הלמד מענינו, דבר שחיבין עליו מיתת בית דין: **ולא תכחשו.** לפי שנאמר (ויקרא ה כב) וכחש בה, משלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תכחשו: **ולא תשקרו.** לפי שנאמר (שם) ונשבע על שקר, ישלם קרן וחומש. למדנו עונש, אזהרה מנין, תלמוד לומר ולא תשקרו: **לא תגנבו ולא תכחשו ולא תשקרו ולא תשבעו.** אם גנבת, סופך לכחש, סופך לשקר, סופך להשבע לשקר:
@12 **ולא תשבעו בשמי.** למה נאמר, לפי שנאמר (שמות כ ז) לא תשא את שם ה' אלהיך לשוא, יכול לא יהא חיב אלא על שם המיוחד, מנין לרבות כל הכנויין, תלמוד לומר ולא תשבעו בשמי לשקר, כל שם שיש לי:
@13 **לא תעשק.** זה הכובש שכר שכיר: **לא תלין.** לשון נקבה מוסב על הפעלה: **עד בקר.** בשכיר יום הכתוב מדבר, שיציאתו מששקעה החמה, לפיכך זמן גבוי שכרו כל הלילה. ובמקום אחר הוא אומר (דברים כד טו) ולא תבוא עליו השמש, מדבר בשכיר לילה, שהשלמת פעלתו משיעלה עמוד השחר, לפיכך זמן גבוי שכרו כל היום, לפי שנתנה תורה זמן לבעל הבית עונה לבקש מעות:
@14 **לא תקלל חרש.** אין לי אלא חרש, מנין לרבות כל אדם, תלמוד לומר (שמות כב כז) בעמך לא תאר, אם כן למה נאמר חרש, מה חרש מיוחד שהוא בחיים אף כל שהוא בחיים, יצא המת שאינו בחיים: **ולפני עור לא תתן מכשל.** לפני הסומא בדבר לא תתן עצה שאינה הוגנת לו, אל תאמר מכור שדך וקח לך חמור, ואתה עוקף עליו ונוטלה המנו: **ויראת מאלהיך.** לפי שהדבר הזה אינו מסור לבריות לידע אם דעתו של זה לטובה או לרעה, ויכול להשמט ולומר לטובה נתכונתי, לפיכך נאמר בו ויראת מאלהיך המכיר מחשבותיך. וכן כל דבר המסור ללבו של אדם העושהו ואין שאר הבריות מכירות בו, נאמר בו ויראת מאלהיך:
@15 **לא תעשו עול במשפט.** מלמד שהדין המקלקל את הדין קרוי עול, שנאוי ומשקץ, חרם ותועבה. שהעול קרוי תועבה, שנאמר (דברים כה טז) כי תועבת ה' וגו' כל עשה עול, והתועבה קרויה שקץ וחרם, שנאמר (שם ז כו) ולא תביא תועבה אל ביתך והיית חרם כמוהו שקץ תשקצנו וגו' : **לא תשא פני דל.** שלא תאמר עני הוא זה והעשיר חיב לפרנסו, אזכנו בדין, ונמצא מתפרנס בנקיות: **ולא תהדר פני גדול.** שלא תאמר עשיר הוא זה בן גדולים הוא זה, היאך אבישנו ואראה בבשתו, עונש יש בדבר, לכך נאמר ולא תהדר פני גדול: **בצדק תשפט עמיתך.** כמשמעו. דבר אחר הוי דן את חברך לכף זכות:
@16 **לא תלך רכיל.** אני אומר על שם שכל משלחי מדנים ומספרי לשון הרע הולכים בבתי רעיהם לרגל מה יראו רע או מה ישמעו רע לספר בשוק, נקראים הולכי רכיל, הולכי רגילה אשפיימנ''ט בלע''ז [רגול] . וראיה לדברי, שלא מצינו רכילות שאין כתוב בלשון הליכה לא תלך רכיל, הולכי רכיל נחשת וברזל (ירמיה ו כח) , ושאר לשון הרע אין כתוב בו הליכה מלשני בסתר רעהו (תהלים קא ה) , לשון רמיה (שם קכ ב) , לשון מדברת גדולות (שם יב ד) , לכך אני אומר שלשון רכיל לשון הולך ומרגל, שהכ''ף נחלפת בגימ''ל, שכל האותיות שמוצאיהם ממקום אחד מתחלפות זו בזו, בי''ת בפ''א ובוי''ו, גימ''ל בכ''ף וקו''ף, נו''ן בלמ''ד, ורי''ש וז''ן בצד''י וכן (ש''ב יט כח) וירגל בעבדך, רגל במרמה לומר עלי רעה, וכן (תהלים טו ג) לא רגל על לשונו, וכן רוכל הסוחר ומרגל אחר כל סחורה, וכל המוכר בשמים להתקשט בהם הנשים, על שם שמחזר תמיד בעירות נקרא רוכל, לשון רוגל. ותרגומו לא תיכול קרצין, כמו (דניאל ג ח) ואכלו קרציהון די יהודיא, אכל ביה קרצא בי מלכא (ברכות נח א) . נראה בעיני שהיה משפטם לאכול בבית המקבל דבריהם שום הלעטה, והוא גמר חזוק, שדבריו מקימים ויעמידם על האמת, ואותה הלעטה נקראת אכילת קרצין, לשון קורץ בעיניו (משלי ו יג) , שכן דרך כל הולכי רכיל לקרוץ בעיניהם ולרמוז דברי רכילותן, שלא יבינו שאר השומעים: **לא תעמד על דם רעך.** לראות במיתתו ואתה יכול להצילו, כגון טובע בנהר, וחיה או לסטים באים עליו: **אני ה'.** נאמן לשלם שכר, ונאמן להפרע:
@17 **ולא תשא עליו חטא.** לא תלבין את פניו ברבים:
@18 **לא תקם.** אמר לו השאילני מגלך. אמר לו לאו. למחר אמר לו השאילני קרדמך. אמר לו איני משאילך כדרך שלא השאלתני, זו היא נקימה. ואיזו היא נטירה, אמר לו השאילני קרדמך. אמר לו לאו. למחר אמר לו השאילני מגלך. אמר לו הא לך ואיני כמותך, שלא השאלתני. זו היא נטירה, שנוטר האיבה בלבו אף על פי שאינו נוקם: **ואהבת לרעך כמוך.** אמר רבי עקיבא זה כלל גדול בתורה:
@19 **את חקתי תשמרו.** ואלו הן בהמתך לא תרביע כלאים וגו' , חקים אלו גזרות מלך שאין טעם לדבר: ובגד כלאים. למה נאמר, לפי שנאמר לא תלבש שעטנז צמר ופשתים יחדו (דבר' כב יא) , יכול לא ילבש גיזי צמר ואניצי פשתן, תלמוד לומר בגד. מנין לרבות הלבדים, תלמוד לומר שעטנז, דבר שהוא שוע טווי ונוז. ואומר אני נוז לשון דבר הנמלל ושזור זה עם זה לחברו, מישטי''ר בלע''ז [לערבב] , כמו (מועד קטן יב ב) חזיין לנאזי דאית בהון, שאנו מפרשין לשון כמוש פלישטר''א . ולשון שעטנז פרש מנחם, מחברת צמר ופשתים:
@20 **נחרפת לאיש.** מיועדת ומיוחדת לאיש, ואיני ידע לו דמיון במקרא. ובשפחה כנענית שחציה שפחה וחציה בת חורין המאורסת לעבד עברי שמתר בשפחה, הכתוב מדבר: **והפדה לא נפדתה.** פדויה ואינה פדויה וסתם פדיון בכסף: **או חפשה.** בשטר: **בקרת תהיה.** היא לוקה ולא הוא, יש על בית דין לבקר את הדבר שלא לחיבה (י''ג: לחיבו) מיתה: **כי לא חפשה.** ואין קדושיה קדושין גמורין. ורבותינו למדו מכאן שמי שהוא במלקות יהא בקריאה, שהדינים המלקין קורין על הלוקה (דברים כח נח, נט) אם לא תשמר לעשות וגו' והפלא ה' את מכותך וגו' : **כי לא חפשה.** לפיכך אין חיב עליה מיתה, שאין קדושיה קדושין, הא אם חפשה, קדושיה קדושין וחיב מיתה:
@22 **ונסלח לו מחטאתו אשר חטא.** לרבות את המזיד כשוגג:
@23 **וערלתם ערלתו.** ואטמתם אטימתו, יהא אטום ונסתם מליהנות ממנו: **שלש שנים יהיה לכם ערלים.** מאימתי מונה לו, משעת נטיעתו. יכול אם הצניעו, לאחר שלש שנים יהא מתר, תלמוד לומר יהיה, בהויתו יהא:
@24 **יהיה כל פריו קדש.** כמעשר שני שכתוב בו (ויקרא כז ל) וכל מעשר הארץ וגו' קדש לה'. מה מעשר שני אינו נאכל חוץ לחומת ירושלים אלא בפדיון, אף זה כן. ודבר זה הלולים לה' הוא, שנושאו שם לשבח ולהלל לשמים:
@25 **להוסיף לכם תבואתו.** המצוה הזאת שתשמרו תהיה להוסיף לכם תבואתו, שבשכרה אני מברך לכם פרות הנטיעות. היה רבי עקיבא אומר דברה תורה כנגד יצר הרע, שלא יאמר אדם הרי ארבע שנים אני מצטער בו חנם, לפיכך נאמר להוסיף לכם תבואתו: **אני ה'.** אני ה' המבטיח על כך ונאמן לשמור הבטחתי:
@26 **לא תאכלו על הדם.** להרבה פנים נדרש בסנהדרין (סג א) אזהרה שלא יאכל מבשר קדשים לפני זריקת דמים, ואזהרה לאוכל מבהמת חלין טרם שתצא נפשה, ועוד הרבה: **לא תנחשו.** כגון אלו המנחשין בחלדה ובעופות, פתו נפלה מפיו, צבי הפסיקו בדרך: **ולא תעוננו.** לשון עונות ושעות, שאומר יום פלוני יפה להתחיל מלאכה, שעה פלונית קשה לצאת:
@27 **לא תקפו פאת ראשכם.** זה המשוה צדעיו לאחורי אזנו ולפדחתו, ונמצא הקף ראשו עגל סביב, שעל אחורי אזניו עקרי שערו למעלה מצדעיו הרבה: **פאת זקנך.** סוף הזקן וגבוליו. והן חמש שתים בכל לחי ולחי למעלה אצל הראש שהוא רחב ויש בו שתי פאות, ואחת למטה בסנטרו מקום חבור שני הלחיים יחד:
@28 **ושרט לנפש.** כן דרכן של אמוריים להיות משרטין בשרם כשמת להם מת: **וכתבת קעקע.** כתב המחקה ושקוע שאינו נמחק לעולם שמקעקעו במחט והוא משחיר לעולם: **קעקע.** לשון (במד' כה ד) והוקע אותם, (שמואל ב כא ו) והוקענום. תוחבין עץ בארץ ותולין אותם עליהם ונמצאו מחקין ותחובין בקרקע, פורפויינ''ט בלע''ז [נעוץ] :
@29 **אל תחלל את בתך להזנותה.** במוסר בתו פנויה לביאה שלא לשם קדושין: **ולא תזנה הארץ.** אם אתה עושה כן הארץ מזנה את פירותיה לעשותן במקום אחר ולא בארצכם. וכן הוא אומר (ירמיה ג ג) וימנעו רבבים וגו' :
@30 **ומקדשי תיראו.** לא יכנס בהר הבית לא במקלו ולא במנעלו ובאפונדתו ובאבק שעל רגליו. ואף על פי שאני מזהירכם על המקדש, את שבתותי תשמרו אין בנין בית המקדש דוחה שבת:
@31 **אל תפנו אל האבת.** אזהרה לבעל אוב וידעוני. בעל אוב זה פיתום המדבר משחיו. וידעוני מכניס עצם חיה ששמה ידוע לתוך פיו והעצם מדבר: **אל תבקשו.** להיות עסוקים בם, שאם תעסקו בם אתם מטמאין לפני ואני מתעב אתכם: **אני ה' אלהיכם.** דעו את מי אתם מחליפין במי:
@32 **מפני שיבה תקום.** יכול זקן אשמאי, תלמוד לומר זקן, אין זקן אלא שקנה חכמה: **והדרת פני זקן.** איזהו הדור, לא ישב במקומו ולא ידבר במקומו ולא יסתור את דבריו. יכול יעצים עיניו כמי שלא ראהו, לכך נאמר ויראת מאלהיך, שהרי דבר זה מסור ללבו של עושהו, שאין מכיר בו אלא הוא, וכל דבר המסור ללב נאמר בו ויראת מאלהיך:
@33 **לא תונו.** אונאת דברים. לא תאמר לו אמש היית עובד עבודה זרה ועכשיו אתה בא ללמוד תורה שנתנה מפי הגבורה:
@34 **כי גרים הייתם.** מום שבך אל תאמר לחברך: **אני ה' אלהיכם.** אלהיך ואלהיו אני:
@35 **לא תעשו עול במשפט.** אם לדין, הרי כבר נאמר לא תעשו עול במשפט (פסוק טו) , ומהו משפט השנוי כאן, הוא המדה והמשקל והמשורה. מלמד שהמודד נקרא דין, שאם שקר במדה הרי הוא כמקלקל את הדין וקרוי עול, שנאוי, ומשקץ, חרם ותועבה. וגורם לחמשה דברים האמורים בדין מטמא את הארץ, ומחלל את השם, ומסלק את השכינה, ומפיל את ישראל בחרב, ומגלה אותם מארצם: **במדה.** זו מדת הארץ: **במשקל.** כמשמעו: **ובמשורה.** היא מדת הלח והיבש:
@36 **אבני צדק.** הם המשקולות ששוקלין כנגדן: **איפת.** היא מדת היבש: **הין.** זו היא מדת הלח: **אשר הוצאתי אתכם.** על מנת כן. דבר אחר אני הבחנתי במצרים בין טפה של בכור לטפה שאינה של בכור, ואני הנאמן להפרע ממי שטומן משקלותיו במלח להונות את הבריות שאין מכירים בהם:
@39 **ואל בני ישראל תאמר.** ענשין על האזהרות: **מות יומת.** בבית דין, ואם אין כח לבית דין עם הארץ מסיעין אותן: **עם הארץ.** עם שבגינו נבראת הארץ. דבר אחר עם שעתידין לירש את הארץ על ידי מצות הללו:
@40 **אתן את פני.** פנאי שלי, פונה אני מכל עסקי ועוסק בו: **באיש.** ולא בצבור, שאין כל הצבור נכרתין: **כי מזרעו נתן למלך.** לפי שנאמר מעביר בנו ובתו באש (דברים יח י) , בן בנו ובן בתו מנין, תלמוד לומר כי מזרעו נתן למלך. זרע פסול מנין, תלמוד לומר בתתו מזרעו למלך: **למען טמא את מקדשי.** את כנסת ישראל, שהיא מקדשת לי, כלשון (ויקרא כא כג) ולא יחלל את מקדשי:
@41 **ואם העלם יעלימו.** אם העלימו בדבר אחד, סוף שיעלימו בדברים הרבה. אם העלימו סנהדרי קטנה, סוף שיעלימו סנהדרי גדולה:
@42 **ובמשפחתו.** אמר ר' שמעון וכי משפחה מה חטאה, אלא ללמדך שאין לך משפחה שיש בה מוכס שאין כלם מוכסין, שכלם מחפין עליו: **והכרתי אתו.** למה נאמר, לפי שנאמר ובמשפחתו, יכול יהיו כל המשפחה בהכרת, תלמוד לומר אותו. אותו בהכרת ולא כל המשפחה בהכרת, אלא ביסורין: **לזנות אחרי המלך.** לרבות שאר עבודה זרה שעבדה בכך, ואפלו אין זו עבודתה:
@44 **והתקדשתם.** זו פרישות עבודה זרה:
@46 **אביו ואמו קלל.** לרבות לאחר מיתה: **דמיו בו.** זו סקילה, וכן כל מקום שנאמר דמיהם בם. ולמדנו מאוב וידעוני שנאמר בהם באבן ירגמו אותם דמיהם בם (פסוק כז) . ופשוטו של מקרא, כמו דמו בראשו (יהושע ב יט) , אין נענש על מיתתו אלא הוא, שהוא גרם לעצמו שיהרג:
@47 **ואיש.** פרט לקטן: **אשר ינאף את אשת איש.** פרט לאשת קטן, למדנו שאין לקטן קדושין. ועל איזו אשת איש חיבתי לך: **אשר ינאף את אשת רעהו.** פרט לאשת גוי, למדנו שאין קדושין לגוי: **מות יומת הנאף והנאפת.** כל מיתה האמורה בתורה סתם אינה אלא חנק:
@49 **תבל עשו.** גנאי. לשון אחר מבלבלין זרע האב בזרע הבן:
@50 **משכבי אשה.** מכניס כמכחול בשפופרת:
@51 **ישרפו אתו ואתהן.** אי אתה יכול לומר אשתו הראשונה ישרפו, שהרי נשאה בהתר ולא נאסרה עליו, אלא אשה ואמה הכתובין כאן, שתיהן לאסור, שנשא את חמותו ואמה. ויש מרבותינו שאומרים, אין כאן אלא חמותו. ומהו אתהן, את אחת מהן, ולשון יוני הוא הן אחת:
@52 **ואת הבהמה תהרגו.** אם אדם חטא בהמה מה חטאה, אלא מפני שבאה לאדם תקלה על ידה, לפיכך אמר הכתוב תסקל. קל וחמר לאדם שיודע להבחין בין טוב לרע וגורם רעה לחברו לעבור עברה. כיוצא בדבר אתה אומר (דברים יב ב) אבד תאבדון את כל המקומות, הרי דברים קל וחמר, מה אילנות שאינן רואין ואינן שומעין על שבאת תקלה על ידם אמרה תורה השחת, שרוף וכלה, המטה את חברו מדרך חיים לדרכי מיתה על אחת כמה וכמה:
@54 **חסד הוא.** לשון ארמי חרפה (בראשית לד יד) חסודא. ומדרשו אם תאמר קין נשא אחותו, חסד עשה המקום לבנות עולמו ממנו, שנאמר (תהלים פט ג) עולם חסד יבנה:
@55 **הערה.** גלה. וכן כל לשון ערוה גלוי הוא, והוי''ו יורדת בתבה לשם דבר, כמו זעוה, מגזרת (אסתר ה ט) ולא קם ולא זע, וכן אחוה מגזרת אח. והעראה זו נחלקו בה רבותינו, יש אומרים זו נשיקת שמש, ויש אומרים זו הכנסת עטרה:
@56 **וערות אחות אמך** וגו' **.** שנה הכתוב באזהרתן, לומר שהזהר עליהן בין על אחות אביו ואמו מן האב בין על אחיותיהן מן האם, אבל ערות אשת אחי אביו לא הזהר אלא על אשת אחי אביו מן האב:
@57 **אשר ישכב את דדתו.** המקרא הזה בא ללמד על כרת האמור למעלה, שהוא בענש הליכת ערירי: **ערירים.** כתרגומו בלא ולד, ודומה לו (בראשית טו ב) ואנכי הולך ערירי. יש לו בנים קוברן, אין לו בנים מת בלא בנים, לכך שנה בשני מקראות אלו ערירים ימותו ערירים יהיו. ערירים ימותו, אם יהיו לו בשעת עברה, לא יהיו לו כשימות לפי שקוברן בחייו. ערירים יהיו, שאם אין לו בשעת עברה, יהיה כל ימיו כמו שהוא עכשו:
@58 **נדה הוא.** השכיבה הזאת מנדה היא ומאוסה. ורבותינו דרשו לאסור העראה בה כנדה, שהעראה מפורשת בה (פסוק יח) את מקורה הערה (לעיל יח) :
@60 **ואקץ.** לשון מיאוס, כמו (בראשית כז מו) קצתי בחיי, כאדם שהוא קץ במזונו:
@62 **והבדלתם בין הבהמה הטהרה לטמאה.** אין צריך לומר בין פרה לחמור, שהרי מבדלין ונכרין הם, אלא בין טהורה לך לטמאה לך, בין שנשחט רבו של סימן לנשחט חציו. וכמה בין רבו לחציו, מלא שערה: **אשר הבדלתי לכם לטמא.** לאסור:
@63 **ואבדל אתכם מן העמים להיות לי.** אם אתם מבדלים מהם הרי אתם שלי, ואם לאו הרי אתם של נבוכדנצר וחבריו. רבי אלעזר בן עזריה אומר מנין שלא יאמר אדם נפשי קצה בבשר חזיר, אי אפשי ללבוש כלאים, אבל יאמר אפשי, ומה אעשה ואבי שבשמים גזר עלי, תלמוד לומר ואבדיל אתכם מן העמים להיות לי, שתהא הבדלתכם מהם לשמי, פורש מן העברה ומקבל עליו עול מלכות שמים:
@64 **כי יהיה בהם אוב** וגו' **.** כאן נאמר בהם מיתה ולמעלה כרת. עדים והתראה בסקילה, מזיד בלא התראה בהכרת ושגגתם חטאת, וכן בכל חיבי מיתות שנאמר בהם כרת:

@2 **אל כל עדת וגו'**. טעם אומרו אל כל. אמרו ז''ל בתורת כהנים לפי שפרשה זו רוב גופי התורה תלוים בה נאמרה בהקהל. והגם שכל מצוה ומצוה ממצות התורה היה משה אומרה לכל ישראל כאמור בברייתא הובאה בעירובין (נד:), תירץ הרא''ם שהיו נכנסים כת אחר כת מה שאין כן בפרשה זו שנכנסו יחד ע''כ. וקשה לדבריו אם כוונתו באומרו שהיו נכנסים כת אחר כת על ישראל שהיו באים אחר הזקנים, אם כן משה הי' אומר יותר מחמשה וששה פעמים, ולפי חשבון הפעמים שמנה התנא שם שיש ביד כל אחד ד' אינו משמע כן, שכתבו וזה לשונם נכנסו כל העם וכו' נמצאו ביד אהרן ד'. ואם כוונת הרב באומרו כת אחר כת הוא על כת של אהרן, ונדב ואביהוא, וכת של הזקנים, וכו' שבשאר הציוויים היו נכנסים זה אחר זה וכאן נכנסו יחד אהרן נדב ואביהוא והזקנים והישראלים. הנה במה שנעמוד על עקרן של דברים למה משה נהג בכל המצות בסדר זה, ולא היה שונה לכולם יחד ד' פעמים, ונמצאו לכל אחד מישראל ד' פעמים מפי משה, שהוא יותר טוב מלשמוע הד' פעמים פעם ממשה וב' וג' פעמים מזולתו, אלא הטעם הוא לא' מב' דברים, או לעשות כבוד להדרגת ישראל כבוד לאהרן כבוד לבניו כבוד לזקנים ואחר כך לישראל, או לצד שכל אחד למד בפני עצמו מפי משה כשיחזור אהרן לבניו וכשיחזרו בניו לזקנים והזקנים לישראל מאמצעות זה יהיה ניכר ונרגש אם יש השתנות בנשמע בין הכתות כשיחזרו הדברים זה לזה, מה שלא היה הרגש זה אם היו כלם שומעים מפי משה הד' פעמים, ודבר זה יושכל בלב שומע. אם כן לב' הדרכים יותר נכון לעשות בסדר זה גם במצוה זו, בין לטעם לעשות כבוד לאהרן כו' למה יגרע כבוד אהרן וכו' כאן, בין לטעם שיכון הדברים לשומעים אדרבה כאן יצטרך להיות הדבר יותר לצד שהם גופי התורה. ואם לצד שיאמר משה המצוה בדרך כללי לכל ישראל, הלא גם בסדר הראשונות ישנה לבחינה זו שישנו לדיבורו של משה כללי לכל ישראל כשנכנסין כל ישראל ושונה להם משה במעמד גם אהרן ובניו והזקנים, ואם כן מה כיעור בסדר הרגיל שצוה ה' לשנות שאין זה אלא גרעון:
@2 **אכן** הנכון בעיני הוא, כי בסדר הראשון לא היה מדבר משה אלא לאנשים, וכאן צוה ה' שידבר לכל עדת ישראל אנשים ונשים וטף כסדר שהיו מקובצים במתן תורה. ובסמוך יתבאר הכתוב באופן אחר:
@2 **ואמרת אליהם**. טעם שכפל לומר ואמרת לדבריהם ז''ל (ויק''ר פכ''ד תו''כ) שאמרו כי לצד שרוב גופי התורה וכו' לזה עשה בה גם כן כסדר נתינת התורה שדבר בה רכות וקשות (יתרו יט ג) כה תאמר וגו' ותגד, ואמר דבר לשון קושי **ואמרת** אמירה רכה, ובסמוך יתבאר הכתוב באופן אחר:
@2 **קדושים תהיו**. צריך לדעת מה הוא המכוון של מצוה זו. ונראה שבא הכתוב לתת עשה על העריות, שציוה עליהם בפרשה הקודמת בלאו, הוסיף עשה עליהם לעבור עליהם גם בעשה. עוד ירצה על דרך אומרם ז''ל (קידושין לט:) ישב אדם ולא עבר עבירה נותנים לו שכר כעושה מצוה, והוא מאמר הכתוב קדושים תהיו במצות עשה בבא עבירה לידו שיתרחק מעשות', ובזה קיים מצות עשה שנצטוו במאמר **קדושים תהיו**, והוציא זכרון מצוה זו בלשון זה של **קדושים**, לומר שכל המקיים מצוה זו נקרא קדוש, והוא מאמרם ז''ל (ויק''ר פכ''ד ירושלמי יבמות פ''ב ה''ד) ג''כ. ולטעם זה דקדק לומר **אל כל עדת בני ישראל**, לומר כי מצוה זו שמצוה קדושים תהיו היא מצוה שישנה בכל אדם, שכל איש ישראל בקיימו מצוה זו קדוש יאמר לו, ואין הדרגה בישראל שתהיה נמנעת מהשגה זו. גם בזה יתישב טעם כפל דבר ואמרת, כי יש כאן דיבור קשה בערך העובר שיוסיף עונש עשה, ויש כאן מעלה וכבוד למקיימו שיקרא קדוש. ואולי כי דוקא בנ''י הוא שישנם בבחינה זו מה שאין כן אומות העולם, לו יהיה שיפרוש אדם עצמו מבחינות העריות האסורות לו או אפילו שאינם אסורות, אף על פי כן מושלל הוא מבחינת הקדושה, ולזה אמר **אל** וגו' **בני ישראל**, ובסמוך יתבאר באופן אחר:
@2 **כי קדוש אני וגו'**. צריך לדעת מה נתינת טעם הוא זה, וכי יתחייב הדבר ליציר כפיו להדמות לקונו, והלא הרבה הדרגות ישנם באלהי ישראל ואינם מושגים בישראל, ואם כונתו לומר טעם הציווי שהוא חפץ בדבר לצד אלהינו קדוש חפץ שגם עובדיו יהיו כמו כן ולא טעם המתחייב, ועד עתה אין אני יודע למה יתחייב הכתוב לתת טעם. ורז''ל נראה שמקושיא זה הרגישו, ודרשו בתורת כהנים וזה לשונם אם אתם מקדשים עצמיכם מעלה אני עליכם כאילו קדשתם אותי ע''כ. וכפי זה תהיה כוונת **כי קדוש** וגו' הודעת תועלת הנמשך, והודעת הפכו כמו שסיים שם התנא ואם אין אתם מקדשים עצמכם מעלה אני עליכם כאלו לא קדשתם אותי ע''כ. ואולי כי גם לזה כוון בכפל דבר ואמרת, לקושי הנמשך אם לא יקדשו עצמם, ולרוממות הנסבב אם יקדשו עצמן:
@2 **עוד** נראה לפרש הכתוב על זה הדרך כי לצד שצוה ה' על בחינת תאוה הקבועה בטבע אנושי, והוא תאוה השולטת על הרצון, וכבר כתבתי בפרשה הקודמת בפסוק (יח ב) כמעשה ארץ מצרים וגו' כי בחינה זו אין יכולת באדם לשלוט עליה אלא בגדר הריחוק בבחינת החושב, ומעתה לצד שצוה ה' במקומו לקיים המין ולהדבק בצלע נכון לאיש יש מוצא רע מבחינה זו להתגבר בו בחינת חשק המתגבר ונוצח הרצון בהופכו, ואין אדם שולט בעצמו להשמר מן העריות שצוה ה' עליהם, ואם כן ממה נפשך יעשה מצוה דרך גבר בעלמא לקיים מינו הנה הוא מושלל משמירת העריות, ימנע עצמו ממין זה כל עיקר הנה הוא מבטל מצות פריה ורביה ומצות יבום, אשר על כן בא מאמר ה' כאן וצוה בנעימות אמרי קדוש **קדושים תהיו** פירוש שיקדשו עצמן במעשים אשר באה עליהם המצוה לעשותה, פירוש שלא יעשה הדבר לתאות הגשם ולהשלים החפץ השואלו עשות דבר אלא יעשה הדבר בקדושה ובטהרה, כמו שמתעטף בציצית ומכניס תפילין בזרועו, וימאס בדעתו חפץ הבא מעצמו, והוא מאמרם ז''ל (נדרים כ:) יהיה דומה כמו שכפאו שד, ולאיש כזה קדוש יאמר לו, ולצד שיאמר אדם איך נכחיש המורגש שהחפץ יכירנו ויטעה טעם הדבר, ואין כח בבחינת החושב למנוע ההרגש בזה כי הרגשתו גדולה ומעוררת כל החושים והרגשות וכובשת המחשבה לבא עמהם בטעימת הדבר, ואם כן חזרנו לחששא הראשונה, לזה אמר **כי קדוש אני ה' אלהיכם**, פירוש על דרך אומרם ז''ל (תיקונים ע) כי כל העושה מצוה אחת שמו יתברך הוי''ה שורה על אבר שבו עשה המצוה, כי תיבת המצוה בו רמוז שם, מ''צ בא''ת ב''ש י''ה, ואותיות ו''ה הרי הוי''ה, וכבר כתבתי במקומות אחרים (לעיל יח ד) טעם שחצי השם בא''ת ב''ש וחצי נגלה. ואם כן בעשות האדם הדבר לשם מצוה הנה שם הוי''ה שורה עליו שהוא קדוש, ובזה אין דבר רע משתלשל מהמעשה, והוא אומרו **כי קדוש אני ה' אלהיכם**, דקדק לומר **אלהיכם** לרמוז אל דביקות ה' במתקדש לעשות המעשה לשם מצוה, על דרך אומרו ואתם הדבקים בה' אלהיכם. ולזה אמר **אל כל עדת בני ישראל** לומר שכל איש ישראל ישנו בגדר מצוה זו, גם כפל ואמרת לרמז מעלה זו:
@2 **עוד** ירצה באומרו **כי קדוש אני** וגו' פירוש לצד שיש מאמרו יתברך בתורה שעם בני ישראל הם דבוקים בהקב''ה דכתיב (שם) ואתם הדבקים וגו', ועל ידי עבדיו הנביאים כתוב לאמר (ידמי' יג) כאשר ידבק האזור אל מתני איש כן הדבקתי אלי את כל בית ישראל, מעתה בא הקב''ה בטענה הנשמעת ואמר **קדושים תהיו**, והטעם כי קדוש אני, ואם תאמר ומה לתבן את הבר, לזה אמר ה' **אלהיכם**, כאן רמז השראת שכינה בדבקות לה' כאמור בפסוק ואתם הדבקים בה' אלהיכם:
@2 **עוד** ירצה שלא יאמר אדם שלא אסר הכתוב אלא מעשה העריות אבל לא בחינת החושב והסתכלות ושאר דקדוקי התיעוב אשר רבו וכבר רמזו מהם רז''ל (ברכות סא.) כגון המרצה מעות מידו ליד אשה וכו', כמו שדרשו בפסוק יד ליד וגו', וכאן צוה ה' על הדברים ההמה וכיוצא בהם שצריך להרחיק עצמו מהכיעור ומהדומה לדומה לו כדי שלא יבא להכשל אפילו בדקדוקים ההם, וכמאמר הזוהר בפסוק אל תפנו אל האלילים, והוא מה שצוה במאמר קדושים תהיו לבל יבא לידי החושב ותהיה נשללת מהם בחינת הקדושה כמאמר הכתוב (תצא כג יא) לא יהיה טהור מקרה לילה, ולצד שיאמר אדם הלא דבר זה אינו ברשותי שהגם שאשמור עצמי ביום אף על פי כן בלילה אין הדבר תלוי בידי, לזה אמר **כי קדוש אני ה' אלהיכם** וכיון שאני קדוש ואני עמכם אני אמנע בחינת הטומאה מגשת לאיש הישראלי, זולת אם אדם יחשוב בבחינת הרע אז שולל ממנו השראת שכינה ושורה עליו בחינת הרע והוא ההדרוקן המכסה פני איש רע, ואז יבא לידי קרי בלילה:
@2 **עוד** ירצה על זה הדרך **קדושים תהיו** לשון עתיד פירוש אין הפסק למצוה זו, כי כל שער מהקדושה אשר יכנס עדיין ישנו בגדר הכנסה שער אחר למעלה ממנו, כי אין שיעור להדרגות הקדושה המזומנת לכל הרוצה ליטול את השם. וצא ולמד ממדרגות הנביאים זו למעלה מזו, ומשה עולה על גביהן, ואולי שיכול להיות הדרגה גדולה ממשה, והוא מדרגות מלכנו משיחנו המעוטר בעטרי עטרות, כמובן מפסוק (ישעי' יא) ונחה עליו רוח ה' וגו', ולדברי רז''ל (במד''ר פי''ט דב''ר פ''ב) כי משה שהיה הוא הגואל העתיד, וכמו שהארכנו בפירושן של דברים במקומן, אם כן אין שיעור וגבול להדרגות הקדושה. לזה אמר **תהיו** כי מצוה זו אין לה הפסק ותמיד ישנה בגדר מצוה זו להיות קדושים. ונתן טעם לדבריו **כי קדוש אני ה' אלהיכם** שאין שיעור אל קדושתו יתברך, וחפץ ה' בבניו ידידיו להדמות לקונם בהפלגת הקדושה, ומעתה דון בדעתך ההדרגות אשר תבא בהם:
@2 **עוד** ירצה בנתינת הטעם **כי קדוש** וגו' פירוש ולפי ערך גדולת קדושתו יתברך צריכין להתקדש כי לצד שאנו מכינים עצמינו להשראת שכינה על ראשינו צריכין לשער גודל קדושתו יתברך כדי לעשות המוכן לדבר, כי אינו דומה המאכסן בביתו הדיוט, למאכסן שר וגדול וקל וחומר מלך, וקל וחומר בנו של קל וחומר מלך המלכים, וקל וחומר וכו' מלך העולם אשר לו המלוכה, שכל מה שיעשה עדיין ישנו בקום עשה כי אין שיעור די להצריך עשות, ולזה אמר **כי קדוש אני ה' אלהיכם** פירוש ולערך קדושתי אני מצוה שתכינו עצמכם בכל יכולת המושג:
@2 **ותמצא** שאמרו ז''ל (שבת קיב:) אם הראשונים כמלאכים וכו' ואם הראשונים אנשים וכו', הראת לדעת כמה צריך אדם עשות בהתקדשותו. וצא ולמד כמה היו משתדלים בעבודת ה' הראשונים, ממעשה רבי אלעזר בן עזריה (שם נד) שיצתה פרת שכנתו ברצועה שבין קרניה שלא ברצון חכמים הגם כי כפי דעתו היה מותר, ואמרו בירושלמי (שבת פ''ה) שהושחרו שיניו בתעניות על הדבר ההוא ולזה כיון באומרו **דבר** לשון קושי לצד הפלגת הציווי. ולצד בחינת המושג אמר **ואמרת** ואמר **אל כל עדת בני ישראל** לבל יאמר אדם שאין מצוה זו הגדולה לכל איש ישראל ולא דבר הכתוב אלא ליחידי סגולה, לזה אמר **אל כל עדת** וגו' שכלם ישנם בגדר מצוה זו, והוא מאמרם ז''ל (תדב''א רמב''ם הל' תשובה) יכול אדם לעשות עצמו כמשה רבינו:
@2 **עוד** ירצה **קדושים תהיו** כמלאכים הנקראים קדושים, ככתוב (דניאל ח) ויאמר אחד קדוש, והוא על דרך אומרו (תהלים פב) אני אמרתי אלהים אתם ובני עליון כלכם, ולצד שהקב''ה השרה שכינתו בתוך בני ישראל ועשאם בני פלטין שלו במקום המלאכים, וצא ולמד מה שאמרו בספר הזוהר (ח''ב קמ:) על זמן שהשרה הקב''ה שכינתו בתחתונים כמה היתה הרגשת בני עליון על שבחר ה' באוכלסי ישראל יותר מאוכלוסי המלאכים, ולזה צוה ה' את אוכלוסיו המובחרים שהן הנה מלאכיו ולהם יקרא קדושים וכשנכנסת' בגדר זה להיות אוכלוסי במקום המלאכים צריכין להיות קדושים. ורמז פרט זה שנכנסו במקום אוכלוסת המלאכים באומרו ה' **אלהיכם**:
@3 **איש אמו וגו'**. טעם סמיכות מצוה זו למצות קדושים. נתכוון לרמוז גם כן גדר לעריות, והוא על דרך מאמרם ז''ל (סוטה לו:) שדרשו בפסוק ויפוזו זרועי ידיו מידי אביר יעקב וגו' כי כשתקפתו אשת פוטיפר ליוסף ותקפו יצרו נזדמנה לו דיוקן אביו ואמר לו וכו' מיד ויפוזו זרועי וגו'. ושמעתי משם אנשי אמת (קב היש פ''ב) כי דיוקן האב תגביר כח הקדושה בבן ותמנעהו מבוא אל התיעוב והוא אומרו סמוך למצות העריות **אביו ואמו תיראו**, ולזה מי שתקפו יצרו יצייר בין עיניו יולדיו ויהיה לו למשיב נפש:
@3 **גם** ירמוז כי בעשותו המזימתה יבזה כבוד אביו, ולזה יצו האל סמוך למצות העריות מצות מוראו של אב ואם, הא למדת שאם גילה עריות בטל מצות מורא אב ואם שגרם להם זלזול שיאמרו ארור שזו ילד וכו', ולדרך זה הקדים האם לאב לצד שהיא נוטלת החרפה ביותר, על דרך אומרו (משלי י) ובן כסיל תוגת אמו. ולדרך זה הרווחנו טעם נכון גם בסמיכות **ואת שבתותי תשמרו**, והוא על דרך אומרו ז''ל בזוהר (ח''ב רעז ח''ג ש''א) כי ז' צדיקים יתכנו להם ז' ימי השבוע, ואמרו בזוהר חדש (ריש פ' תולדות) כי יום שבת הוא כנגד יוסף הצדיק, והוא סוד השלום ולזה אנו אומרים שבת שלום ואנו מברכין הפורם סכת שלום, והיא בחינת יסוד הכל ויוסף לצד צדקתו אשר שמר אות ברית קודש מגשת אל הטומאה ירש בחינה זו. והוא מה שאמר כאן **ואת שבתותי** ב' שבתות א' שמירת עצמו מלטמא אות ברית קודש, וא' שמירת שבת ושניהם בחינה אחת, ולזה נקראים שניהם אותות, בשבת אמר (תשא לא יג) אות היא ביני וגו'. ובמילה אמר (לד יז יא) והיה לאות. ותדע כי ב' הבחינות בערך המעשי הם ב' אבל בערך המסובב מהם הוא בחינה אחת והשומר אחד מהם יסובב התיקון והתקשרות נפשו בב' המצות, ולזה אמר **ואת שבתותי**:
@3 **ואביו תיראו**. בתורת כהנים אמרו שבמקום אחד הקדים הכתוב אב לאם דכתיב (יתרו) כבד את אביך ואת אמך וגו', ובמקום אחר הקדים אמו וכו' לומר ששניהם שקולים אבל אמרו חכמים האב קודם לאם. גם הברייתא הובא בקידושין דף ל''א דרש רבי וזה לשונם גלוי וידוע לפני מי שאמר והיה וגו' שבן מכבד לאמו וכו' לפיכך הקדים כבוד אב וכו' וגלוי וידוע וכו' שהבן מתירא מאביו וכו' לפיכך הקדים ה' מורא האם וכו' ע''כ. וקשה לי לב' הדרשות, כי כשנשכיל בענין בב' הכתובים החשיב הכתוב האב יותר מהאם בפסוק כבד וגו' הסמיך האב לכבוד באומרו כבד את אביך, גם בפסוק זה הסמיך האב למורא באומרו ואביו תיראו, ובדרך הזה מצינו לרז''ל שדרשו בכמה מקומות. והן אמת אם לא היה דין יוצא מדרך זה הייתי יכול לפרש הכתוב כדברינו שכבר הרשות נתונה לנו לפרש הכתוב הגם שיהיה בסדר אחר משונה מדברי הראשונים כל שאין הדין משתנה, אבל במה שלפנינו ישתנה הדין, אם נתגרשה האם, כי לפי מה שפרשנו שהתורה הקדימה בב' המקראות האב לאם אם יאמר אביו השקינו מים ואמו אומרת השקיני מים אם להקדים אביו לאם, ולדברי רבותינו שאמרו שהם שוים אלא לצד שהוא ואמו חייבין בכבוד אביו אם נתגרשה שאין טעם זה רצה יקדים לאביו רצה יקדים לאמו. וכן אמרו שם בקידושין בשאלת בן אלמנה אחת את רבי אליעזר ורבי יהושע, וזה לשונם נתגרשה מהו אמר לו הטל להם מים בספל וכו' ע''כ. הרי לסברת ר''א שקולים הם ממש. ואולי כי לפי מה שדרשו ז''ל שם בתורת כהנים וזה לשונם איש אין לי אלא איש אשה מניין תלמוד לומר תיראו אם כן למה נאמר איש מפני שהאיש סיפק בידו אשה אין סיפק בידה לעשות ע''כ, הנה לדברי ברייתא זו נאמר איש למעט אשה בענין הכבוד אמור מעתה שלענין הכבוד נאמר איש אמו וגו', ובאם אינו ענין, וכפי זה ישנה להקדמת אם בבחינת הכבוד, וכל זה ליישב ברייתא דתורת כהנים. אבל לדרשת רבי שדרש שהקדים הכתוב אם לאב בבחינת המורא וכו' עדיין קשה. ואולי כיון שאין זה אלא דרך אגדה ואין יוצא מזה דין הדרשה תדרש, שהרי סוף סוף הקדים הכתוב אם לאב שהיה לו לומר איש יירא אמו ואביו, והגם שהוכרח הכתוב לדבר בסדר זה לומר איש למעט אשה מחיוב הכבוד ולומר תיראו לרבות בבחינת המורא, אף על פי כן סוף סוף הרי סדר האם קודם לאב והאגדה נתלית ברמז כל שהוא:
@3 **עוד** נראה לומר כי התנאים לא נראה להם לומר שלצד שהסמיך הכתוב זכרון המורא לאב יהיה גדול מהאם. מטעם שהכתוב הוכרח במעשיו לדבר בסדר זה איש וגו' תיראו כדי שנדרוש מיעוט ורבוי בנשים, וכיון שכן נאמר בפה מלא שהקודם בפסוק הוא הראשון, ואמר תיראו לבסוף לא להסמיך לה האב כדי שיהיה במעלה יותר מהאם אלא לדרוש ממנה רבוי חיוב האשה במורא הורים:
@3 **עוד** נראה לומר טעם שאמר לשון יחיד וגמר אומר לשון רבים, נתכוון לומר כי כשהבן יהיה ירא מאביו גורם גם כן שבנו יהיה ירא ממנו, איבעית אימא למה שקדם בדברינו במקומות אחרים (ויחי מט ג) כי שורשי הקדושה ונגדיהם הנמצאים במוליד יעשו כיוצא בהם בנולדים. ואיבעית אימא מדרך המוסר כי כשיראה הבן שאביו מזלזל בכבוד אביו יפקע כלילת מוראו גם כן ממנו, וכשאדם ירא מאביו וכו' הבן לוקח מוסר. גם ישרישו בנפש הבן בחינת מפעל הטוב, ונמצא מקיים ב' מוראים, והוא אומרו **איש** לשון יחיד **תיראו** לשון רבים, כי במורא א' יראים ב', וזה אומרם (אבות פ''ד) מצוה גוררת מצוה:
@3 **או** יאמר על דרך מה שפסק הטור סימן ר''מ וזה לשונו ונראה לי כיון שהוא רשע אינו חייב בכבודו כדאמרין (ב''ק צד:) גבי הניח להם פרה גזולה חייבין להחזיר משום כבוד אביהם, ופריך בש''ס והלא לאו עושה מעשה עמך ואין חייבין בכבודו, ומשני כשעשה תשובה, אלמא כל שלא עשה תשובה אין חייבין בכבודו עכ''ל. סובר הרב שאין להחזיקו בעשה תשובה אלא כשראינוהו שעשה דוקא. והוא מאמר הכתוב **איש אמו ואביו** פירוש איש שמתנהג עם אמו כמנהג אב ואם לזה תיראו אבל מי שמזלזל בכבוד אביו ואמו פטור ממורא. ותיבת אמו ואביו חוזרת לאיש המוליד ונמשכת גם כן לתיראו להגיד על מי באה מצות תיראו והבן. וגם לפי מה שכתבתי בחבורי פר''ת והעמדנו דברי רמב''ם שכתב שמן הסתם מוחזק בחזר בתשובה, והוכחתו מההיא שאמרו בש''ס (קידושין מט) באומר לאשה הרי את מקודשת לי על מנת שאני צדיק גמור וכו' שאנו אומרים עשה תשובה הגם שלא ראינוהו שעשה וכו', ודחינו ראית הטור שהביא מהניח להם אביהם פרה גזולה, כי שאני ההוא שמעשיו מוכיחים שלא חזר בתשובה שהרי עודנה לפרת חטאתו עומדת חיה אף כי אחרי מותו, אבל כל שאין הוכחה כזו מן הסתם יעמוד בחזקת שחזר, גם לפי זה יעמדו דברינו בזמן שאנו רואים ודאי שאינו מכבד ואין מקום לחוש לתשובה, וכדומה להניח פרה גזולה, איש כזה פקע כבודו ומוראו מבניו כאשר עשה:
@3 **עוד** ירצה על דרך אומרם ז''ל בההיא עובדא דההוא גברא וכו' ושמע ושמתיה משום לפני עור לא תתן מכשול, והוא מאמר הכתוב כאן תיראו לשון רבים הגם שלא צוה אלא לאחד דכתיב איש אף על פי כן המצוה מוטלת על הירא ועל המתירא לבל יגרום למצוה שלא ירא שלא יסובבהו ליכשל:
@3 **ואת שבתותי תשמרו וגו'**. רז''ל אמרו (ב''מ לב:) מנין שאם אמר לו אביו חלל שבת וכו' שלא ישמע לו דכתיב איש אמו וגו' ואת שבתותי וגו' אני ה' שאתה ואביך חייבין בכבודי ע''כ. הנה לטעם אתה ואביך וכו' שדרשו מאומרו אני ה' מובן כי כמשפט הזה יהיה בכל מצות התורה הגם שאינם חמורים כשבת כגון השבת אבידה וליטמא למתים, אם כן למה לא הסמיך אלא מצות שבת שהיא חמורה שהיה לו להסמיך מצוה אחרת קלה, גם בזה לא היה צריך לנתינת טעם אני ה' להביא ממנה שאר מצות קלו'. ויתבאר על פי מה שכתב רמב''ם בפרק ה' מהלכות ממרים וזה לשונו היו אביו ואמו רשעים גמורים וכו' אסור לו להכותם וכו' ע''כ. ודייקו כל האחרוני' כי דוקא להכותם אסור אבל כבודם ומוראם אינו חייב בו. והעליתי בחיבורי על יורה דעה בישוב דברי רמב''ם עם מה שכתב הפרק ז' מהלכות ממרים שחייב לכבדם, כי לא כ' כן אלא במי שעבר קצת עבירות לתיאבון באקראי, וכאן מדבר במי שהוחזק ברשע גמור, ולזה דקדק בלשונו רשעים גמורים ולא הספיק לומר רשעים. וסובר אני שרשעים גמורים הם עוברים על כל העבירות הבאות לידם אלו אינו חיוב על הבן לירא מהם ולכבדם. והוא מאמר הכתוב כאן **איש אמו ואביו תיראו** ותנאי הוא הדבר **ואת שבתותי תשמרו** כלכם אבות ובנים, ודוק מינה שאם האבות לא ישמרו שבתות ה' הרי פקע מצות מוראם כי שקול שבת כנגד כל התורה כולה (שמו''ר פכ''ה י''ב) ונקרא רשע גמור:
@3 **עוד** יתפרש כל הכתוב בדרך רמז בהעיר עוד למה אמר **שבתותי** לשון רבים ולא לשון יחיד כדרך הרגיל בכל התורה. ורז''ל אמרו (שבת סט:) שבא ליתן שמירה אחת לשבתות הרבה, והכוונה בזה שאם עשה מלאכות הרבה בשבתות הרבה בהעלם שבת אינו חייב אלא חטאת אחת. ונראה על דרך מה שאמרו בספר הזוהר (כ''א ה:) כי שבתותי ירמוז ללילה וליום, וזה לשונו דא שבתא ומעלי שבתא כי לילה כיום יתקדש, ולצד שבחינת לילה אינו שוה לקדושת יום כי הלילה הוא בחינת אור המתיחס אליו כלה והוא בחינת שמור, והיום הוא בחינת אור עליון המתיחס אליו בחינת חתן המשפיע באור הלילה כידוע ליודעי חן ולזה יתיחס אליו זכור, ולזה אמר בזוהר (ח''ב פ''ח) כי סעודת לילה היא סעודת חקל תפוחין קדישין וסעודת יום היא סעודא עתיקא קדישא אב הרחמים, ולזה יקרא קידוש היום בלשון חז''ל (פסחים קו.) קידושא רבא.
@3 ושמעתי גם ראיתי כתוב (בסוף שו''ע האריז''ל) מעשה שבימי ראב''ע עמד טועה אחד וכתב בראיות כי יום שבת יקדים בו היום ואחר כך הלילה ונתגלה הדבר להרב על ידי נס וסתר מועצותיו וכו' דרשו מעל ספרו (אגרת שבת), וכנגד דעת טועה זו דבר הכתוב ואמר **איש אמו ואביו תיראו** הקדים אם לאב והשוה למצוה זו מצות השבת ואמר **ואת שבתותי** שהם לילה ויום וכו' לומר שגם בהם יקדים בחינת האם שהיא לילה לבחינת האב שהוא היום, שכסדר הורים כן סדר שבתות מעלי שבתא ושבתא ולא כדעת הטועים הנזכרת:
@4 **אל תפנו**. אומרו לשון פניה, לאסור מחשבת עבודה זרה, שלא יהיה פונה בדעתו לחשוב בה. ולהשכילך על דבר אמת דע כי בחינת אלהים אחרים תתיחם לה בחינת אחוריים, וכשהאדם חושב בה הם פונים אותם לצד פנים, והמשכיל יבין:
@4 **האלילים**. אמר לשון רבים, לצד שבחינת הרע היא בחינת הפירוד ואין חלק בה שיהיה לאחד, ולזה כשיזכיר הכתוב אלהים אחרים יזכירם בכינוי רבים:
@4 **ואלהי מסכה וגו'**. קשה והלא צוה בדרך כלל על כל האלילים שלא לפנות להם, ומה צורך לחזור ולצוות על זה. עוד למה אמר **לכם**. ואולי שיכוין למה שאמרו ז''ל (תיקונים יח) כי בעשות האדם מעשה הגון תשרה עליו שכינה, ובעוברו פי ה' האבר שבו חטא שורה עליו רוח הטומאה, והוא מסך המבדיל בינו ובין אלהיו כדרך אומרו (ישעי' נט) עונותיכם מבדילים וגו', והוא מאמרו כאן **ואלהי מסכה** פירוש אלהים שהם מסכים מבדילים אתכם ממקור החיים לא תעשו אותם לכם, הא למדת שהפונה לעבודה זרה גורם מסך המבדיל בינו ובין קונו, ולזה גמר אומר **אני ה' אלהיכם** לומר ממי הוא נבדל מצד המסך הלז:
@4 **עוד** יכוין באומרו אני ה' אלהיכם כי במה שישמור עצמו מאיסור זה של עבודה זרה בזה ה' אלהיו על דרך אומרם (חולין ה.) כל הכופר בעבודה זרה כמודה בכל התורה כולה. ובדרך רמז יכוין על דרך אומרם ז''ל (מגילה כח.) בפסוק לולי פני יהושפט וגו' מכלל שאסור להסתכל בפני אדם רשע, והוא אומרו כאן **ואלהי מסכה לא תעשו לכם** פי' לא תעשו עצמיכם אלהי מסכה שאסור להסתכל בכם:
@8 **ונכרתה וגו'**. יש לתת טעם למה יהיה חמור עונש כהן אוכל קדשים חוץ לזמנם חיוב כרת יותר מאוכל נבילה וטרפה ושקצים. דע כי מן הטעם עצמו שאמרו (ב''מ קיד:) ישראל מטמא באוהל ואין עכו''ם מטמאין באוהל לצד שישראל הם בחינת הקדושה ולזה כשמסתלקת ממנו הקדושה כל הקליפות מתקבצים יחד ובאים עליו. והוא הטעם עצמו במה שלפנינו, כי לצד שהקדשים ישנם במעלה שאין למעלה ממנו, כשעבר זמן אשר צוה ה' בו מסתלקת הקדושה ושורה עליו טומאה גדולה אשר כורתת נפש אוכלתה, מה שאין כן בטומאת אכילת שאר איסורים כנבילות וטריפות שקצים וכו' שאין כח בטומאה ההיא להכרית הנפש, ומתטהרת במלקות. ואומרו **כי את קודש ה' חלל** שנראה שיקפיד על בשר הקודש ולדברינו יקפיד על נפש האוכל' דבר טומאה. אולי כי לצד שעל ידי אכילת הבשר הוא משלים מעשה השלמים, לזה כשאוכלים הבשר יש בזה חילול הקודש שגומר מה שכבר נעשה על ידי מעשה זה, והוא בשר טמא ומחלל את אשר כבר בא בקודש מהדם והחלבים, וזו גם כן סיבה להשראת טומאה גדולה על הבשר ההוא, כי בחינת הרע תקוה ותשאף למקום הסבוך וסרוך לקדושה:
@9 **ובקצרכם וגו'**. טעם שהתחיל לדבר בלשון רבים וגמר אומר בלשון יחיד **לא תכלה**, נתכוון לשלול דעת טועים אשר אומרים כי כשאין דבר מספיק לעניים אין לו ליתן, על דרך אומרו (מלכים ב ד) מה אתן זה לפני מאה וגו', לזה צוה ה' בלשון יחיד לומר שאפילו אחד לבד עליו חובת פאה, הגם כי פאה של אדם אחד מועטת היא לכל עניי ישראל, וכמו כן במצות לקט ופרט ועוללות אמר לשון יחיד מטעם הנזכר. וטעם סמיכות מצוה זו לעונש כרת. אולי שרמז שלא יאמר אדם אם הזיד ונתחייב כרת מעתה אין לשמור עצמו מכל אשר יזדמן לפניו במעשה הרע כי כבר נתחייב כרת, לזה אמר **ובקצרכם את קציר ארצכם** פירוש כשגרם עד שנקצר קציר ארצו שהוא כרת האמור בסמוך **לא תכלה פאת שדך לקצור** אותה במעשים רעים אחרים. והודיע בזה שלא תכרת כל הנפש אלא הענף שבו רמוז מצוה זו, ועדיין ישנה לראות אחרים דבוקים בשורשם, כי כל נפש ישראל יש לה שרשים למעלה כנגד כל מצות התורה ואמר **ולקט קצירך** וגו', פירוש אפילו בענף החטא עצמו לא יוסיף לחטוא, כי יש לך לדעת מאמר הרב האר''י ז''ל כי בטבע הקדושה להשאיר במקום שתהיה בו רושם. ואם כן הגם שנכרת עדיין יש השארות הקציר שם, והוא שצוה עליו **ולקט קצירך לא תלקט** ברוב פשעים, כי ה' חפץ שבאמצעות הלקט ההוא יתעורר וישוב בתשובה לפני ה' וירחמהו, כי הלא תמצא שאמרו ז''ל (יומא פו.) שאפילו עבר אדם על כריתות ומיתות בית דין תשובה וכו' מכפרין, וכמאמר הנביא (הושע יד) שובה וגו' עד ה' אלהיך ודרשו ז''ל (שם) גדולה תשובה שמגעת עד כסא הכבוד פירוש שהגם שנכרת החוט המחבר עד כסא הכבוד ולא נשאר אלא חלק קטן בקרבו התשובה מגיעתו עד כסא הכבוד:
@11 **לא תגנובו וגו'**. סמך מצות גניבה למצות פאת שדה. אולי שנתכוין על דרך מה שאמרו בתורת כהנים (כאן) וזה לשונם בן בג בג אומר לא תגנוב את שלך מהגנב שלא תראה כגונב ע''כ. וכאן נתכוין במה שסמך לא תגנובו לפאה, שבא עליה באזהרה לבל יגנוב אותה בחושבו כי שלו הוא לוקח. ופירוש ג' לאוין אלו הוא, **לא תגנובו** זה הלוקח ממון חבירו שלא מידיעתו.
@11 **לא תכחשו** זה הבא לידו ממון חבירו בהיתר ומכחיש כשתובעו ממנו.
@11 **לא תשקרו** זה הבא לידו ממון חבירו בעדים והוא מכחיש, הגם שלא תועיל לו הכחשתו לענין ממון, הרי זה עובר משום לא תשקרו:
@11 **עוד** ירמוז שאם אדם עבר על הראשונה וגנב, הקב''ה יזמין לו מכירין, על דרך אומרם ז''ל (חגיגה טז. במד''ר פ''ט) העובר עבירה בסתר הקב''ה מכריז עליו ומפרסם רשעתו, ואם כן אם גנב ה' יזמין מי שידע בגנבתו, ומצוה אותו ה' שלא יכחיש, והוא אומרו **לא תכחשו**, ומדבר הכתוב באופן שיכול להכחישו כגון שאין כאן אלא עד אחד, אם הודה מה טוב ואם הכחיש הרואה, הקב''ה יזמין לו עד שני שיעיד עליו שאינו יכול להכחיש, ואם יכחיש שקר בימינו ולא יועילו שקריו, והוא אומרו **לא תשקרו** שמלבד שלא הועילו מעשיו הנה הוא עובר גם על לאו זה. וטעם אומרו לשון רבים מה שלא אמר בסדר זה עד עתה גם במצות הסמוכות מלאחריו אמר לשון יחיד דכתיב לא תעשוק וגו'. ונראה שנתכוין להזהיר גם בזמן שיכיר אחד בחבירו שגנב או כחש וכו' שלא יאמר אעשה כן גם אני להציל את שלי, לזה אמר לשון רבים **לא תגנובו** פי' הגם שהוא גנב לא תוסיף אתה להרשיע כמוהו ותעשו שניכם גנבים. וכמו כן אם יכחיש חברך לא תוסיף גם אתה עשות כמוהו ותכחשו שניכם. וכמו כן אם שקר בך חברך וכו', ואמר **ולא תשבעו** ג''כ שלא יאמר אם הוא מכיר שחבירו נשבע לו לשקר הריני נשבע להציל ממוני ממנו, ונשבעין לאנסים, שהרי אתה מחלל שם וכו', ולזה גמר אומר לשון יחיד, לומר שמדבר עם מי שמציל ממון עצמו בשבועה, ואין צריך לומר הנשבע ראשון הרמוז בכלל לא תשבעו. עוד יכוין באומרו **לא תשבעו** להזהיר גם למשביע אם יודע שחברו נשבע לשקר שלא ישביעהו, ואינו בחילול אלא הנשבע לזה אמר **וחללת** לשון יחיד:
@13 **לא תעשוק וגו'**. הכונה, להיות שצוה ה' על נוטל ממון חבירו שלא בידיעתו, אל יאמר אדם שלא הקפיד אלא בדרך גניבה אבל גזילה ועושק אשר ידע האדם בהם אין אזהרה, לזה חזר לצוות גם על נוטל ממון חברו בידיעתו כאונם, ולא גזילת ממון בהחלט לבד אלא אפילו עכבת ממון שכיר אסור. וטעם אומרו **רעך**, נתכוון לשלול טענת היותו ריעו ובאמצעות זה יתן יד בממונו ויאמר כרע כאח לו בינו לבין עצמו ימחול לו ולא יחפוץ להענישו, ולצד שאין באזהרה זו אלא משום דברים שבין אדם לחברו, כשהוא מוחל אין עון, לזה אמר **לא תעשוק את רעך**:
@13 **ובדרך** רמז ירמוז על דרך מה שדרשו חז''ל (ברכות לה:) בפסוק גוזל אביו ואמו וגו' זה הנהנה מהעולם הזה בלא ברכה ע''כ, והוא מאמר ה' כאן **לא תעשוק את רעך** זה הקב''ה דכתיב (משלי כז) ריעך וריע אביך שלא יגזול ברכות שהוא חייב לברך על מה שנהנה בעולם הזה, ואומרו **ולא תגזול** רמז שגם בעושק זה יש גזילה לאחרים, שהוא מה שרמז בפסוק גוזל אביו ואמו ודרז''ל (שם) אביו זה הקב''ה אמו זו כנסת ישראל, כי כשהאדם ממעיט במצוה הצריך עשות גורם רעה גם לכללות ישראל ואמר **לא תלין** שצריך לתת חוק יום ביומו, על דרך אומרם ז''ל (ויק''ר פכ''ו) שהיו לוים ביום ופורעים בלילה, והוא מה שרמז כאן לא תלין פעולת שכיר **אתך** פירוש תיבת אתך חוזרת לשכיר שהוא רוח ה' אשר נתן באדם כשכיר כתושב, ושכרו הוא עשות מצות ה':
@13 **עוד** ירמוז על דרך אומרם ז''ל כי בני תורה אין להם פרנסתם בעולם הזה וכאומרם (ילקוט משלי רמז תתקל''דד) שאמרה תורה מפני מה בני עניים, והטעם הוא שמעתי טעם נכון משם האר''י ז''ל כי אין העולם יכול לסבול רוב הטובה אשר תנתן בשביל הצדיקים לזה אינו משפיע אלא לבינונים ודרך שם יהיו נזונים בני תורה, הא למדת שאין העשירים אלא מרזב אשר הוכן להסתפקות הצורך לצדיקים, וצוה ה' לבל יעשוק האדם את ריעו שהוא הצדיק דכתיב (תהלים קכב) למען אחי ורעי ולא יתן לו את חקו, וזה עושק מפורסם:
@13 **עוד** ירמוז שלא יעשוק תיבת את שאצל ריעך שהוא הקב''ה, כמו שדרש רבי עקיבא (פסחים כב:) את ה' אלהיך תירא לרבות תלמידי חכמים. והכונה בזה לירא מהחכמים הדנים בארץ, וכיון שכן הרי יש אלהים שופטים בארץ אשר ירא מהם לקיים דבר משפט, ובזה לא יגזול כי השופט יוציא גזילה ממנו:
@15 **לא תעשו עול במשפט**. אזהרה זו באה לבעלי דינים שלא יערימו לזכות כפי הדין, והוא עול ולזה אמר בלשון רבים לא תעשו וגו', ושיעור אומרו **עול במשפט** הוא על זה הדרך, במשפט אשר ישפטו הדיינים שלא יסובבו שיהיה בו עול, כי הדיין שופט על פי הטענות אשר יסדרו לפניו, ולזה סמך מצוה זו לאזהרת לפני עור וגו' כי זה מכשיל הדיין לשפוט משפט מעוול:
@15 **עוד** ירצה לומר שהגם שהמשפט זכהו, לא יסמוך לעשות עול כשיכיר בעצמו כי עול בימינו, ולזה אמר בלשון רבים כי ידבר לבעלי דינים, ובסמוך שכוונתו לצוות לשופט אמר לשון יחיד לא תשא לא תהדר וגומר:
@15 **עוד** יכוין באומרו **לא תעשו עול** אזהרה לדיין, שהגם שהמשפט יגיד לחייב את זה ולזכות את זה אם בעיניו נראה כי הוא עול לא יעשו עול זה בשביל מה שנתחייב במשפט, אלא אין לדיין אלא מה שעיניו רואות:
@15 **עוד** ירצה באומרו **במשפט** בה''א הידיעה, על דרך אומרם ז''ל (ביצה טז.) כי בראש השנה קוצב הקב''ה לכל איש ואיש הצריך לו על משפט צדק, ולזה אם יחייבו הזכאי ויזכו החייב הנה הוא יוצא עול במשפט עליון בסך קצוב וכשמחסרו אם כן נעשה העול במשפט שלא נטל זה מה שחייב בבית דין של מעלה, וכן להיפך:
@16 **לא תלך רכיל וגו'**. קדמו רז''ל בספר הזוהר הקדוש ודקדקו כפל הדברים, **תלך**, **רכיל**, כי אחת הנה, ואמרו דרך סוד יעיין שם דבריהם באדרא (פ' נשא קכח.) ולפי פשט הכתוב נראה שיכוין לומר שלא יגרום הוא הרכילות הנעשה מהזולת על ידו, הא כיצד שלא יגלה דברים אפילו למי שאין בהם רכילות במקום שיש לחוש שהשומעים יוליכו הדברים ונמצא הוא הוליך רכילות זו שרכלו האמצעים. ולדרך זה ידוייק אומרו **בעמך**, פירוש באמצעות עמך אתה מוליך רכיל שאומרים הדברים בפניהם ומתגלגלים מזה לזה ונשמעים הדברים, ואמר **אני ה'** פירוש אני בוחן הדברים ממי יצאו תחילה ופורע:
@16 **עוד** ירצה שלא יחזיק בידי מדברי לשון הרע שבזה הוא סובב שיוליכו הרכיל ומעלה עליו הכתוב כאלו הוא הוליך רכילות לזה להיותו סיבה:
@16 **לא תעמוד וגו'**. לצד שצוה על הרכילות התנה בו שלא יעמוד על דם רעך, שאם ראה כת אחת שרוצין לרצוח חייב להודיעו לבעל דבר כדי שיציל נפשו, ולא יאמר הרי זה רכילות, הא למדת שאם לא גילה אוזן חבירו והרגוהו בטל אזהרת לא תעמוד וגו'. וצא ולמד ממעשה גדליה בן אחיקם (ירמי' מ) שגילו לו וכשלא חש היה מה שהיה:
@17 **לא תשנא את אחיך וגו'**. פירוש אם נסבב מאחיך דבר הגורם לשנאתו לא תשנאהו בלבבך אלא בפיך דבר אליו תוכחות על אשר ככה סבב, והוא אומרו **הוכח** וגו'. ואומרו **ולא תשא עליו חטא**, פירוש לא תחליט בדעתך שמה שנסבב מאחיך ברשע עשאן ועודנו עומד בחטאו עמוס על שכמו אלא תהיה דן אותו לכף זכות, ותוכיחנו ועל ידי התוכחה יהיה אחד מב' דברים, או יתן אמתלא להנעשה ואין חטא, או יתחרט על הנעשה וישוב לבל עשות כדבר הזה, והרי הוא כריע כאח לך:
@17 **עוד** נראה לפרש בהעיר עוד בשיעור הנדבר שהיה צריך לומר לא תשנא בלבבך את אחיך, שיגמור מקום השנאה שהתחיל לדבר בה ואחר כך יזכור את מי ישנא. אכן יכוין להודיע שיעור השנאה אשר ה' מצוה עליה, שלא יאמר אדם שאינו קרוי שנאה אלא שנאה גמורה לבקש רעתו ולחפוץ בכליונו, אבל הרחקה בלב אינה קרויה שנאה, לזה נתחכם הכתוב לסמוך **לא תשנא** עם תיבת **אחיך** לומר כי השערת השנאה אשר יצוה ה' עליה היא הנרגשת בערך אח, ושיעור זה כל שירחיקהו מלבו קצת הנה הוא יורד ממדרגת אח, והרי הוא עובר משום לא תשנא:
@17 **עוד** ירצה בהעיר למה באזהרת לא תשנא דקדק לומר את אחיך ובאזהרת הוכח תוכיח אמר את עמיתך שנראה שמדבר בב' נושאים:
@17 **אכן** יתבאר על דרך אומרם ז''ל (תיקונים ה' תדבא''ר פ''ג) אם ראית תלמיד חכם שעבר עבירה ביום אל תהרהר אחריו בלילה כי ודאי עשה תשובה גם מצינו שאמרו ז''ל (פסחים קי''ג:) בפרשת כי תראה חמור שונאך וגו' שהכתוב מדבר במי שראה בחברו רבר מגונה שמצוה לשנאותו. וכאן צוה הכתוב שאם ראה דבר מגונה בתלמיד חכם אינו נכלל בגדר אותם שצוה ה' לשנאותם אלא צריך להחזיקו כי ודאי עשה תשובה, והוא אומרו **לא תשנא את אחיך** שהוא תלמיד חכם המתכנה בשם אח דכתיב (תהלים קיג:) למען אחי ורעי. או על דרך אומרם את ה' אלהיך תירא לרבות תלמידי חכמים, כמו כן כאן **את אחיך** פירוש המתרבה מאת אחיך, ותיבת אחיך חוזרת על הבורא ב''ה שנקרא אח לישראל (מי שוחר טוב כ''ג) כביכול. ואומרו **הוכח תוכיח** מדבר בנושא אחר שהם המון העם, ולזה אמר **את עמיתך** ולא אמר הוכח תוכיחנו וחוזר לאחיך שאמר בתחילה אלא לומר שאינו מדבר במה שהתחיל לדבר בו שהוא תלמיד חכם אלא כהמון העם שמצוה לשנאותו מצוהו ה' שיוכיחנו על פניו למה תעשה כה בנעימות לשון בחיבה וברכות לשון. ואומרו **ולא תשא עליו חטא**, פירוש שלא ימנע ממנו התוכחות שבזה ישאר במשא חטאו ולא ישוב אל ה', הא למדת שאם לא הוכיחו בטל עשה דהוכח ולא תעשה של ולא תשא:
@17 **עוד** ירצה על דרך אומרם ז''ל (כתובות קה:) האי צורבא מרבנן דסנו ליה בני מאתיה משום דמוכח להו במילי דשמיא. ומעתה יאמר החכם למה לי קנאה למה לי שנאה ותחרות עם זרע ישראל ואחדל מהוכיח ואהיה אהוב ונחמד לכולן, לזה נתחכם ה' וקודם שצוהו להוכיח צוה לבני ישראל שלא ישנאוהו ואחר כך צוהו להוכיח שהרי ישראל מוזהרים מה' לבל ישנאוהו. ואם תאמר ומי יערבנו לעם שלא ישנאוהו וישמרו מצות לא תשנא, לזה אמר **ולא תשא עליו חטא** פירוש שלא יחשדם בחטא זה אלא יחזיקם בכשרות. ואומר לשון יחיד לשלול החשד אפילו מיחיד שיחזיק כל איש ישראל שלא ישנאו בשער מוכיח, ובזה יוכיח ויחזור ויוכיח עד שיקבלו מוסרו:
@17 **עוד** ירצה על דרך אומרם ז''ל (שבת לג:) בעון הדור נתפסים גדולי עולם, וכן הוא אומר (שה''ש א) אשכול הכופר וגו', ולצד זה חש הכתוב שתכנס בלב קרובי ה' הרחקת הלב על מעשה ה' זה, כי יאמרו שאינם מובטחים בחייהם ובשלוותם הגם כי יפליאו להטיב מעשיהם, לזה בא דבר ה' כאן ואמר לצדיקיו לא תשנא את אחיך בלבבך, פירוש אחיך זה הקב''ה, ויש לך לדעת שלא לכל ישראל בהשוואה יקרא הקב''ה אח אלא להקרובים והדבקים בה' כרבי עקיבא וחביריו, וצוה להם שלא יתרחק לבם מה', שההרחקה היא ענף השנאה. ואם תאמר מה אשיב אל לבי לבטחון בחיי ובשלוותי, לזה אמר **הוכח תוכיח את עמיתך** ובזה לא תשא אתה עליו פירוש בשבילו חטא, כי כלום טעם תפיסת הצדיק הוא בשביל עון הדור אם יוכיחנו הרי הוא ניצול ממה נפשך, אם חזרו בתשובה הרי אין כאן עונות שיתפס עליהם, ואם לא חזרו הרי נפטרת מתפיסה, כמו שגילה סודו ביד עבדיו הנביאים דכתיב (יחזקאל לג) ואתה כי הזהרת רשע וגו' הוא רשע בעונו ימות ואתה את נפשך הצלת. ולדרך זה נתיישבו כל הדקדוקים שדקדקנו בפ ס וק:
@17 **שוב** בא לידי תנא דבי אליהו (רבה פי''ח) וזה לשונו וכי באחים מן האב והאם הכתוב מדבר אין הכתוב מדבר אלא כנגד הקב''ה שאין לו אחים לא בעולם הזה ולא בעולם הבא ולא לימות המשיח אלא צדיקי עולם שעושין רצונו בתורתו בכל יום שקרא אותם אחים וריעים עכ''ל, ותדע שמעלת אח יותר ממדרגת בנים, כמאמר ז''ל (שה''ש פ''ג) לא זז מחבבה עד שקראה בתי לא זז וכו' עד שקראה אחותי:
@18 **לא תקום וגו'**. רז''ל (תו''כ כאן יומא כג.) אמרו נקימה הוא שעושה לו כמעשהו הרע נטירה שלא יאמר לו לא אעשה לך כמעשיך. וכפ''ז נתן טעם הכתוב למצוה זו בסמיכות ואהבת לרעך כמוך, פירוש כי ה' חפץ שתהיה אוהב רעך כמוך ואם אתה אומר לו כן הרי גלית דעתך כי טמון היה בלבך מעשהו בלתי הגון לך, ונתן טעם לדבר אני ה', פירוש על דרך אומרם (זוהר ח''ג טז) שבאמצעות יחוד הלבבות מתייחד שמו יתברך להיות שכנסת ישראל הם ענפי שם הוי''ה ב''ה דכתיב (דברים לב) כי חלק ה' עמו, ונתחכם ה' לצוות בענין הנהגת ישראל זע''ז בהדרגה. מצוה א' לא תשנא. ב' לא תקום וגו'. ג' ואהבת, ודקדק לומר, אחיך, עמך, לומר שאין מצוה אלא על אנשים שעושים מעשה עמך, אבל שונאי ה' כגון המומרים והאפיקורסים אסור לאהוב אותם ואדרבה צריך לשנאותם, כאומר (תהלים קלט) הלא משנאיך ה' אשנא:
@19 **את חקותי וגו' בהמתך וגו'**. בתורת כהנים אמרו וזה לשונם אין לי אלא בהמתו, בהמת חבירו מנין, תלמוד לומר את חקותי ע''כ. וקשה אם כן למה הוצרך הכתוב לומר **בהמתך** היה לו לומר בהמה לא תרביע כלאים ואז לא היה צריך לרבות בהמת אחרים. וראיתי להרב בעל קרבן אהרן שכתב בזה שדבר הכתוב בהווה. ואין דבריו נראים לי, כי לא ידבר בהווה במקום שיש לטעות ויצטרך להוסיף דברים להסיר הטעות:
@19 **ונראה** בהעיר בסדר הכתובים למה סמך הכתוב מצות הרבעה למצות אהבת ריעים, ומי יודע לסדר סדר מתאים כה' אלהינו. אכן לצד שצוה ה' על אהבת החברים והתקשרות לבם יחד כי חפץ ה' התקשרות ענפי הקדושה, ומזה יאמר אדם כי לא יקפיד ה' על הרבעת טהורה עם טהורה, לזה בא הכתוב ואמר כי אין הרצון בזה לקשר בהמה עם בהמה ואפילו בב' ענפי הטהרה הגם ששניהם מין טהרה, ולזה דקדק לומר בהמתך פירוש בהמה הטהורה לך לאכילה, ותמצא שבתורת כהנים דרשו וזה לשונם אין לי אלא בהמה עם בהמה, טהורה עם טמאה, טמאה עם טהורה מנין, תלמוד לומר את חקותי תשמרו עד כאן, הנה שסובר התנא כי בהמתך היא בהמה טהורה ואם לא אמר הכתוב בהמתך לא הייתי יודע שהטהורה בכלל ואדרבה יוכשר המעשה לצד שהוא התקשרות מין טהרה, והגם שהיה ה' מרבה איזה ריבוי הייתי דורשו באחד משאר תערובת טמא וטהור:
@23 **וכי תבואו אל הארץ וגו'**. ג' מצות נאמרו כאן. א' ביאת הארץ על דרך אומרם (כתובות קי:) הכל מעלין לארץ ישראל וכו'. ב' לנטוע כל עץ מאכל לשבח הארץ. ג' לנהוג שני ערלה:
@23 **עוד** ירמוז באומרו **וכי תבאו אל הארץ** שלא תהיה הכוונה לתיאבון המורגשות אלא תהיה כוונת הביאה אל הארץ לחיבוב ולחשק הארץ הקדושה אשר בחר ה' בה הר ה' שמה, ואמר כי אין כוונת דיבור זה להחליט המניעה מהשתדל בישוב הארץ אלא ונטעתם וגו', הא למדת שמה שהתנה במאמר אל הארץ הוא בבחינת תכלית המחשבה שתהיה למעלת הארץ במושכלות לא להנאת הגוף ואולי שרומז באומרו **עץ מאכל** על בני תורה שגם הם נקראו נטעים, כמו שאמר ר' יוסי (שבת קיח:) ה' בעילות בעלתי וה' נטיעות נטעתי, ונקראים גם כן עץ דכתיב (ישעי' ס''ה) כימי העץ ימי עמי, וכמו כן דרשו בזוהר (ח''ג רב) בפסוק לא תשחית את עצה שמדבר באדם בן תורה, ויצו ה' שתהיה עיקר הכנסת הארץ לנטוע בה עץ מאכל שהם בני תורה כי אוירה של ארץ ישראל מחכים ומטהר הנפש (ב''ב קנח:), ונקרא בן תורה עץ מאכל כי ממנו מזון לנפש. וצא ולמד ממעשה של ר' עקיבא (מם' כלה רבתי פ''ב) שלמד תורה לאותו תינוק שהיה אביו מת ונתון בצרה גדולה ומיום שפתח פיו בדברי תורה נהנה אביו בעולם העליון:
@23 **ואמר** ג' שנים **יהיה לכם ערלים**, פירוש אטומים שלא יצא מהם צפצוף תורה שהוא פרי מאכל (תנחומא קדושים יד) שעד שלש שנים אין התינוק יכול לדבר, ובשנה הרביעית שהתחיל לדבר ילמדו לומר תורה צוה לנו, שמע ישראל, וזה יקרא קודש הילולים, ובשנה החמישית תאכלו את פריו כמאמרם ז''ל (אבות פ''ה) בן ה' שנים למקרא, ויתחיל להיות עץ מאכל. וסמך הכתוב לזה מצות **לא תאכלו על הדם**, רמז הכתוב שלא יהיה סיפוקו במאכלו על סיבת הדם שהוא גשם האדם ותכונתו אלא לתכלית המושכל הרמוז בעץ מאכל. וסמך לזה גם כן מצות **לא תנחשו**, כי תכלית אכילת הדם הוא חלק הנחש, בסוד (ישעי' סה) ונחש עפר לחמו, והוא אוכל כל גשם האדם עד כלותו, והוא אומרו **ולא תעוננו** על דרך אומרו (איוב ז) כלה ענן וילך כן יורד שאול לא יעלה, ופסוק זה מדבר בהולך אחר המורגש להרבות חלב ודם:
@26 **לא תאכלו על הדם** סמך הכתוב מצוה זו למצות ערלה, לרמוז מה שאמרו ז''ל (מדרש תלפיות) כי אדם הראשון חטא באכילת עץ הדעת קודם זמן התירו שהוא בחינת ערלה, שאם היה ממתין עד ליל שבת קודש היה מקדש על היין, וזה הוא סוד דבריהם ז''ל שאמרו (סנהדרין לח:) אדם מושך בערלתו היה זו היא ערלתו, והוא מה שאמר הכתוב סמוך לאזהרת וערלתם ערלתו **לא תאכלו** פירוש מפרי ערלה, **על הדם** פירוש על סיבת הדם, כי זו סיבה לכל שפיכות דמים דם אדם ודם זרעיותיו, ויש לך לדעת כי סבת הערלות ועקרם זה מקורם שזולת חטא אדם לא היתה ערלה בעולם לא של צומח ולא של בעלי חיים:
@27 **לא תקיפו וגו'**. בהקפת הראש אמר לשון רבים ובהשחתת הזקן אמר לשון יחיד. לומר שישנו באזהרת לא תקיף הגם שאינו באזהרת לא תשחית, כגון מי שעדיין אין לו חתימת זקן, שלא תאמר כיון שאינו בלא תשחית אינו בלא תקיף כדרך שדרשו (קידושין לה:) במשפט הנשים שאינן בלא תקיפו כיון שאינם בלא תשחית. ואם תאמר ומה ראית לרבות אלו ולמעט אלו, מרבה אני הזכרים שישנם בלא תשחית כשיגדלו, וממעט אני הנשים שאין במינם לא תשחית:
@28 **ושרט לנפש וגו'**. אומרו **לנפש**, לומר הגם שהשרט חיבול הגוף הוא על פרידת הנפש היקרה. ודקדק לומר **לא תתנו בבשרכם**, הודיע הכתוב כי לא יפגום פגם זה בנפש אלא בבשר שהוא נרתק הנפש, והטעם לצד שאדם בהול על מתו אין המעשה פוגם כל כך כעושה בשאט בנפש ובישוב הדעת, ולזה תמצא שאמר הכתוב אחרי זה **וכתובת קעקע לא תתנו בכם** ולא אמר בבשרכם לומר שלא בבשר לבד יגרום הפגם אלא גם בפנימיות האדם לצד שאינו עושה מצד צער וחום הכאב שנאמר בו (ב''ב טז:) אין אדם נתפס על צערו. ואמרו **אני ה'** יתבאר על פי מאמר האלהי הרשב''י (זוהר ח''ג רמז) כי תיבת אני תגיד על כסא כבודו יתברך אשר אנו קוראים שכינתו יתברך, ושם הוי''ה ב''ה הוא מלך יושב על כסא המלכות, ורמז בזה כי יקפיד ה' על כבוד שמו יתברך, ועל כבוד שכינתו, ולדרך זה יצו ה' להאדם לבל יפגום גופו ונשמתו בב' מעשים הרשומים שהם שרט לנפש וכתובת קעקע:
@29 **אל תחלל את בתך וגו'**. פירוש יצו האל למי שיש לו בת שלא ינהג בה מנהג חולין להראותה לפני כל ולהתנאות לפניהם אלא כבודה בת מלך פנימה. והגם שיתכוין בה להנאת זיווגה כדי שיודע כי בת יפה ונעימה היא ותנשא להראוי לה, על כל זה יצו האל כי חילול הוא לה והיוצא מזה הוא להזנותה לא להשיאה כי יבער בה אש הטבעי ותחלל כבודה, ולא זו בלבד אלא שתהיה סיבה להבעיר אש בלב רואה וחומד ותזנה הארץ ולבסוף ומלאה הארץ זימה, ונמצא עון כל הרשע תלוי בצוארו, וצא ולמד מה שפירשתי בפרשת אחרי מות בפסוק (יח ב) כמעשה ארץ מצרים שחוש הראות יגדיל החפץ בדבר ויבטל כח הרצון במניעה ויטהו אל חפץ המעשה רחמנא ליצלן:
@30 **את שבתותי תשמרו וגו** '. צריך לדעת למה חזר לומר פעם ב' מה שצוה בתחלת הפרשה, ורז''ל בתורת כהנים אמרו וזה לשונם יכול יהיה בנין בית המקדש דוחה את השבת תלמוד לומר את שבתותי תשמורו וגומר ע''כ, דבריהם ז''ל יוציאו אותנו מקושי הסמיכות, אבל קושי הכפל במקומו מונח שהיה לו לכתוב ומקדשי תיראו סמוך למאמר ואת שבתותי תשמרו האמור בתחלת הפרשה ולא היה צריך לומר פעם ב' ואת שבתותי וגו':
@30 **ונראה** כי מצוה זו קשורה עם מה שלפניה, כי לצד שצוה ה' לאב לבל יחלל בתו להזנותה לפעמים ימצא כי הבת מעצמה תחלל כבוד עצמה וכבוד אביה לזנות ואין יד האב באמצע לזה צוה ה' לאב שיעשה שמירה לבל תזנה הבת כי הכל תלוי במוליד, ולהיות שיש שלש סיבות אשר יפעילו הולדת טבע רע בנולדים, האחד אם בשעת הזיווג יכוין אל הנאת המשגל לא לסיבת מצות הבורא לקיים המין זה יוליד בנולד תגבות (רע) המין השני ממנה פירוש מצד שהאשה מעשיה לא טובים רחלא בתר תגבורת אזלא. ג' אם המולידים אב או אם חשבו בחינת הרע בהסח הדעת, וכמעשה חזקי' המלך עליו השלום (סנהדרין קד.) אשר מחשבתם סבבה הולדת בלתי הגון הגם היותם יסודי עולם. כנגד סיבה א' אמר **את שבתותי תשמורו** ע''ד אומרם בזוהר (ח''ב פט.) בפסוק לסריסים אשר ישמרו את שבתותי שהם הצדיקים המסרסים את עצמם ואינם נזקקים לנשותיהם אלא בליל שבת ומושכין לבניהם נשמות קדושים ע''כ, הרי שהרוצה להוליד בן בעל נפש טהורה צריך לסרס עצמו ולעצור כח התאב ולא יפעול אלא לתכלית המצוה בו מאת ה' ב''ה והוא מאמר ה' למנוע נפש זונה מביתו **את שבתותי תשמרו** להזדווג בהם ובזה תוליד נשמה קדושה המואסה בזנות, וכנגד סיבה ב' שהוא החשש מצד האם אמר **ומקדשי תיראו** אזהרה לירא מהמקדש ובזה תשמור עצמה האשה לבל יבאינה אל המקדש להשקותה מי המרים. וכנגד סיב' ג' סמך לזה אזהרת **אל תפנו אל האובות ואל הידעונים** הם בחינת הטומאה הרוצה ומתאוה להדבק באדם הטהור. ותיבת **אובות** לשון אבה על דרך אומרו (דברים כג) ולא אבה ה'. ורמז **ידעוני** הוא לומר שלא יחשוב יהיה ידוע אצלו, כי ידיעת הטמא מכרחת האדם להדבק בו כטבע השפל שחפץ להדבק בעליון וחושק:
@30 **ואמר אני ה' אלהיכם**, בא לתת טעם להמשך נפש רעה מסיבת החושב, כי לצד כי ה' אלהינו פירוש שוכן בתוך נפש ישראל בחשוב האדם בבחינת הרע מסתלק כח הקדושה ואין מזדמן לפניו להמשיך אלא חלק הרע, נמצא כי כל שאינו שומר עצמו מג' סיבות הוא מחלל בתו וכו':
@32 **מפני שיבה תקום וגו** ' רז''ל אמרו (קידושין לב:) מפני שיבה שהוא גדול בשנים תקום והדרת קימה שיש בה הידור, תקום והדרת פני זקן זה שקנה חכמה, קשה כפי זה היה לו לומר מפני שיבה ומפני זקן תקום והדרת. ואולי שנתכוין להמשיך ההידור לזקן זה שקנה חכמה והקימה לשיבה שהוא הבא בימים. והכוונה בזה שצריך הדרגה גדולה בכבוד החכם יותר מכבוד גדול בשנים. והגם שדרשו ז''ל קימה והידור לזה וקימה והידור לזה, על כל זה ממה שנתחכם הכתוב לדבר בסדר זה להמשיך הידור לזקן הודיענו כי גדול הידור לזקן מהידור גדול בשנים. ומעתה נמצינו אומרים שצריך לכבד החכם יותר מבעל שיבה:
@32 **עוד** ירמוז על דרך אומרם ז''ל בבראשית רבה (פס''ה) כי אברהם אבינו ביקש על השיבה כדי שיהיה ניכר האב מהבן וכו' דכתיב (בראשית כד א) ואברהם זקן, והוא אומרו **מפני שיבה תקום** ובזה אתה מהדר פני זקן שהוא אברהם דכתיב ואברהם זקן שעל ידו היה דבר זה:
@32 **עוד** ירמוז על דרך אומרם ז''ל (ב''ר פי''ב) כי הרשעים כפופי קומה, ויצו ה' לאדם שיתעורר לתקן מעשיו לשוב לה' וזו היא קומתו, והערו לתקן מעשיו מפני שיבה פירוש שיבתו כדי שלא תאבד ממנו, על דרך אומרם ז''ל (יבמות נ.) זכה משלימין לו לא זכה פוחתין לו ולא יגיע לימי שנותינו ע' שנה. גם רמז כדי שלא יבואו ימים רעים בעת שיבתו שהם יסורין הקשים לאדם מכל יסורין כאומרו ז''ל (קהלת רבה פי''ב) כי הם ימים שכוחות האדם והשתדלותיו אפסים והוא צריך להשגחה אלהות:
@32 **עוד** ירמוז **והדרת פני זקן** פירוש זקנת עצמו על דרך אומרם (סוכה נג.) אשרי ילדותינו שלא ביישה את זקנותנו. גם רמז למאמרם ז''ל (חגיגה יד:) שבשעה שהצדיק הולך מעולם הזה אומרים לאברהם אבינו אשריך אברהם אבינו שצדיק זה יצא מחלציך, וכשהולך הרשע לא די שאין אומרים כן לפניו אלא שהוא מצטער, לזה מעורר ה' להאדם ואומר לו **והדרת פני זקן** זה אברהם שמתהדר כשאומרים לפניו אשריך וכו' והוסיף להפחידו מענייני עולם הבא, ואמר **ויראת מאלהיך** זו יראת עונש יום הדין, **אני ה'** זו תשלום שכר טוב של עולם הבא. או ירצה להעיר היראה והאהבה, יראה ויראת וגו', אהבה אני ד' כי שם זה הוא מקור האהבה החשוקה בלב כל משכיל:
@33 **וכי יגור אתך וגו'**. אמר לשון יחיד **אתך** וחזר לומר לשון רבים בארצכם. לצד כי המשכת הגרים תהיה באמצעות הצדיק אברהם אבינו עליו השלום, גם לצד טוהר ארץ הקדושה תגרר נפשות השבויות, לזה אמר אתך לשון יחיד לרמוז אל הצדיק, כי לא כולן הם בגדר המשכת ענפי הקדושה, ואמר **בארצכם** לרמוז למעשה הארץ, שגם היא ישנה בגדר פעולה טובה זו:
@33 **עוד** ירמוז על השראת השכינה בעולם הזה אתנו, ויצו ה' כי יגור אתך גר ממקום גבוה דקדק לומר אתך על דרך (תהלים עח) אהל שכן באדם. ואמר **בארצכם** היא ארץ הקדושה כי שם מקום השכינה, ועזבה מקומה עליון ובאה לגור בארץ. לא תונו אותו, שאין לך אונאה כאונאת השכינה. ואומרו **כאזרח מכם** וגו' להזהיר על הגרים וכו' הבאים להתיהד:
@34 **כאזרח מכם וגו'**. כאן גילה ה' סודו שכל נפשות עם קדושו היו טבועים במצרים בתוך האומות, והוא מה שאמר כאזרח מכם וגו'. ואם תאמר איך ישוה זרע מריעים שאבותיו גוים לאזרח שאבותיו ידידי ה'. לזה אמר **כי גרים הייתם בארץ מצרים**, פירוש נפשותם היו מעורבים תוך קליפות מצרים, ועיין מה שפירשתי בפרשת יתרו (כ' ב') בפסוק אנכי ה' וגו' אשר הוצאתיך מארץ מצרים וגו', וכמו כן גר זה היתה נפשו תוך הקליפות ועכשיו זרחה בעולם וחזרה לשורשה, וכפי זה ישנו לנתינת טעם לשבח כי גרים וגו', שאם על גרות הגופות אין הטעם נכון כי ישתנה גר הבא מן האומות שלא יהיה נאהב לצד ההבדל שישנו בשינוי המשפחות, כי לא ככל משפחות הגוים בית ישראל:
@39 **ואל בני ישראל וגו'**. טעם אומרו **ואל בני ישראל** נתכוון להזהיר כללות ישראל להרוג הנותן מזרעו למולך, ואמר בתוספת וא''ו לומר שמלבד חיוב המעביר גם חיוב כל העם להענישו:
@40 **ואני אתן את פני וגו'** צריך לדעת מה מקום לעונש זה אחר שיש דין למטה וירגמו אותו אבן:
@40 **ונראה** כי יודיע הכתוב שמלבד עונש ההריגה עוד יהיה לו עונש לנפש, והוא אומרו **והכרתי אותו מקרב עמו** פירוש מענף נצר הקדושה. ונתן הכתוב טעם לב' עונשים אלו ואמר **כי מזרעו** וכו' **למען טמא** וגומר **ולחלל** וגו', הרי ב' פגמים וכנגדן ב' עונשין, כנגד טמא מקדש ירגמוהו באבן, וכנגד חילול שם קדשו גם הוא יתחלל ונכרת נפשו מעמה:
@41 **ואם העלם יעלימו** טעם הכפל, לומר שאם העלימו מן האחד שוב אינם יכולין שלא להעלים מהבאים אחריהם, ויעלימו ודאי מכולם, כי אם ירצו לעשות דין בהם יאמרו להם למה לא עשיתם דין באחד. או יאמר **העלם** לבל ימנעוהו מליתן למולך, **יעלימו** מלעשות בו משפט אחר אשר נתן כאמרו בתתו מזרעו וגומר:
@42 **ושמתי אני את פני וגומר**. משמעות הכתוב יגיד שאם לא יעשה משפט העם יעשה ה' משפט בו ובמשפחתו גם כן, מה שלא היה אם היו עושים דין עם הארץ, ואלו הם דברים רחוקים, ממה נפשך אם הם חייבין בין עשו דין כ''כ ברשע עצמו בין לא עשו:
@42 **ונראה** לפרש על זה הדרך **ואם העלם** וגו' פירוש במקום שאין דין למטה יהיה דין למעלה ושמתי אני וגו'. וכשיעשו דין למעלה יפתחו גם כן פנקסי בני משפחתו ויתעוררו הדינים על כל המשפחה, והוא אומרו **ובמשפחתו**. וחזר ופירש שימת פנים זו מה עושה, ואמר כנגד האיש עצמו והכרתי אותו, וכנגד משפחתו יפתחו ספרי דיניהם אם יש מהם זונים כמותו הרי הוא בכלל הכרת, והוא אומרו ואת כל הזונים אחריו ממשפחתו, אבל אותם שנפתחו ספריו ונמצא שלא זנו לא יכרתו, ואמר עוד **לזנות** ולא הספיק לומר הזונים וגו' אחרי המולך, נתכוין לומר שהגם שלא זנה עד עתה פירוש שלא העביר בנו למולך אלא שחשב לזנות מחשבת עבודה זרה נתפסים עליה כמעשה, ויכרית ה' את החושב כעושה כמו שאמר הכתוב (יחזקאל יד) למען תפוש את בית ישראל בלבם:
@42 **נמצאת** אומר שאם עם הארץ יעשו דין בעושה רע אין דין למעלה ולא ימות מישראל זולת העובד למולך, אבל אם לא יעשו דין נפתחים ספרי כל המשפחה ומתעורר הדין גם עליהם ונתפסים גם על המחשבה, והוא מאמרם ז''ל (דב''ר פ''ה) במקום שיש דין וכו' אין וכו' ע''כ. קשה פשיטא שכשיעשו דין למטה מה מקום לדין ליעשות למעלה, ולדרכנו ידוייק על נכון שכשעושין דין למטה נמנע דין למעלה פירוש דין השאר שאין ספריהם נפתחים. ותמצא שאמרו רז''ל (ר''ה טז:) שכשנפתחים ספרי הדינים אדם נכנם בסכנה וצריך זכות גדול ליפטר:
@44 **והתקדשתם והייתם קדושים**. יצו ה' שיהיו נוטים אל בחינת הקדושה, ובזה הוא מבטיחם שיהיו במדריגת מלאכים הנקראים קדושים, דכתיב (דניאל ח) ויאמר אחד קדוש, והוא אומרו **והייתם קדושים**, ותמצא שאמרו ז''ל (במד''ר פ''כ) בפסוק כעת יאמר ליעקב וגו' כי המלאכים יהיו עומדים בשורה החיצונה וישראל בפנים ושואלים מלאכי אלהים לעם קדושו מה פעל אל, נמצאת אומר כי קדושיו במקום המלאכים הם ישראל. וחזר הכתוב ופירש הדבר שבו יתקדשו ואמר **ושמרתם את חקותי**, פירוש תשמרו מצות לא תעשה, ותקיימו מצות עשה בזה אני מקדשכם, כי על ידי זה שם הוי''ה מתגלה עליו ובזה מתקדש, וכמו מה שכתוב בזוהר (תיקונים ע) כי האבר שבו עושה מצוה שורה עליו שם הוי''ה הרמוז בתיבת מצוה:
@46 **כי איש איש אשר יקלל**. קשה אומרו **כי** שנותן טעם למה שלפניו ולא אמר דבר קודש שיהיה זה טעמו. ואם על שמירת החוקים, וכי לא נכלל בפסוק זה אלא קללת אבות שהוצדק לומר כי. עוד למה כפל לומר איש איש. ובתורת כהנים אמרו איש אין לי אלא איש אשה מנין תלמוד לומר איש איש ע''כ. קשה מנין יעלה על דעת למעט אשה שהוצרך לריבוי והלא השווה הכתוב אשה לאיש לכל עונשים שבתורה בדרך כלל וכאומרם ז''ל (ב''ק טו.). ואם לצד שחש הכתוב לפרש איש שבא למעט אשה, לא היה לו לכתוב איש לטעות לומר שבא למעט אשה ויאמר אדם כי יקלל וגו':
@46 **עוד** למה כפל לומר אביו ואמו קלל. אכן כוונת הכתוב הוא לצד שצוה קודם לזה על העברת בנו ובתו למולך, והקפיד הכתוב על זרעו לבד אבל בן אחרים ואפילו קרוביו כגון אחיו ואחותו פטור, כדתניא בסנהדרין (סד:) וזה לשונם אינו חייב אלא על יוצאי יריכו וכו' ע''כ. וצריך לומר טעם חיובו על בנו ובתו ולא על בני הזולת שהוא לצד שבניו הם נידונין כנכסיו של אדם לזה מועילים מעשיו כשמקריבו לעבודה זרה במה שמעבירן למולך אבל חוץ מהם אין מעשיו עושין רושם, על דרך אומרם ז''ל (ערכין כח ב''מ ז.) אפילו לגבי קדשי שמים אין אדם מקדיש דבר שאינו שלו, ומעתה יאמר אדם והלא גם הבן אינו כולו של האב כאומרם ז''ל (נדה לא.) שהאב והאם הם שותפין באדם הלובן מהאב והאודם מהאם, וא''כ מזה הטעם עצמו לא יתחייב האב על הבן מצד חלק האם, לזה אמר הכתוב אחר אזהרה ועונש מעביר בניו למולך כי איש איש אשר יקלל וגו' מות יומת, ודקדק לומר את אביו ואת אמו פירוש זה בפני עצמו או זה בפני עצמו, כמו שדקדקו בתורת כהנים בפסוק זה עצמו חיוב על כל אחד משניהם, הרי שהבן מת לצד שנגע באביו או בכבוד אמו ואין אנו אומרים והרי אין כל הבן של האב או של האם להמיתו בשבילם, ואם תאמר גם על זה דן אנכי למה יהיה המשפט הזה, לזה גמר אומר **אביו ואמו קלל**, פירוש כי כשמקלל אביו מקלל גם אמו עמו וכן להפך, והטעם לצד שהאב והאם הם גוף אחד כמאמרם ז''ל (ברכות כד.) אשתו כגופו, וכפי זה בין הנעשה לאחד מהם או הנעשה מאחד מהם לבניהם יחשב לשניהם יחד. ולזה תמצא שיעניש ה' לאיש להמית אשתו דכתיב (משלי כב) למה יקח משכבך מתחתיך. וכפל לומר **איש איש** משום שמצינו שתלה הכתוב זכרים בנקבות ונקבות בזכרים, ואמרו ז''ל (נדה לא.) אשה מזרעת תחלה יולדת זכר, אם כן יש הפרש בלידת הזכר ללידת הנקבה ומצד זה ישתנה ההפרש בבחינת המולידים, ויש מקום לומר לצד שתלה הכתוב זכרים בנקבות לא יומתו אבות על העברת הבנים או האמהות על העברת הבנות לצד שתלאם הכתוב באבות תלמוד לומר איש איש אחד לגופו ואחד לאשה ששניהם ישנם בחיוב העברת בן ובת:
@46 **עוד** נראה כי לצד שאמר הכתוב אביו ואמו ודרשו רז''ל (ילקוט) שאביו בא למעט אבי אביו ואמו בא למעט אם אמו שלא יהרגו, לזה חש הכתוב לטעות ולומר שהמיעוט בא אביו ולא אביה אמו ולא אמה ואם כן הנשים פטורות מעונש זה, תלמוד לומר איש איש לרבות אשה:
@59 **ושמרתם את וגו'**. טעם שהוצרך לומר פעם אחרת פסוק זה הגם שכבר אמר כן בפרשת אחרי מות (יח כו), נתכוין לומר שצריכין לשמור המצות לבל יתבטלו בין מהם בין מזולתם ובזה לא תקיא הארץ הא למדת שאם לא יהיו נשמרים המצות תקיא הארץ, גם השומרים על שלא מיחו בשלא שמרו:
@61 **ואני אתננה וגו' ארץ זבת וגו'**. קשה אחר שאמר לרשת אותה מה צריך לומר ואני אתננה, עוד למה סמך שבח הארץ לזכרון הירושה. ונראה לי שהכונה היא שמלבד מה שיירשו עוד יתן להם שתהיה הארץ זבת חלב ודבש יותר מהשיעור מה שלפניה, גם שלל שלא בזמן ירושתם אחר כך שהוא זמן החורבן שלא תהיה זבת חלב ודבש, כמו שסיפרו מכיריה בזמן הזה בעונינו:
@63 **והייתם לי קדושים וגו'** טעם אומרו **לי**. יתבאר על דרך אומרם ז''ל (תו''כ כאן) אל יאמר אדם אי אפשי בבשר חזיר וכו' אלא אפשי ואפשי אלא אבי שבשמים וכו', והוא אומרו **והייתם לי קדושים** שתהיו פרושים לי לשם מצותי ולא לצד תיעוב הדבר הנאסר, ולזה סמך מאמר זה להבדלת בהמה וחיה לרמוז למה שכתבתי, ואומרו **כי קדוש אני ה'** וגו' נתן טעם למצוה זו של הבדלת בהמה טמאה כי קדוש וגו' **ואבדיל אתכם מז העמים להיות לי**. והענין עצמו של פרישות ישראל מן העכו''ם הוא הדבר עצמו של פרישתכם מן הבהמה טמאה. ברוך ה' אשר הבדילנו מן הטמאים מאדם עד בהמה עד עוף השמים:
@63 **חסלת פרשת קדושים**
